import React, { useState, useEffect } from "react";
import axios from "../../Https/Axios";
import { EmployeeApiUrl , WorksApiUrl } from "../../Https/AdminSideAxiosUrls"
import Swal from "sweetalert2";

const WorkWithUs = () => {
    const [works, setWorks] = useState([]);
    const [loadingId, setLoadingId] = useState(null); // Track the button loading state

    useEffect(() => {
        axios.get(WorksApiUrl)
            .then(response => {
                if (response.data.entries) {
                    const formattedData = response.data.entries.map(entry => ({
                        id: entry._id,
                        name: entry.name,
                        email: entry.email,
                        phone: entry.phone,
                        address: entry.address,
                        hasLicense: entry.isDivingLicense === "yes" ? "Yes" : "No",
                        licenseNumber: entry.licenseNumber || "",
                        typeOfWork: Array.isArray(entry.services) ? entry.services : [entry.services]
                    }));
                    setWorks(formattedData);
                }
            })
            .catch(error => console.error("Error fetching data:", error));
    }, []);

    // Fetch token from localStorage
    const getToken = () => localStorage.getItem("tchAdminToken");

    // Handle Accept
    const handleAccept = async (work) => {
        setLoadingId(work.id); // Disable the button and show "Accepting..."

        const employeeData = {
            name: work.name,
            email: work.email,
            address: work.address,
            phone: work.phone,
            haveDrivingLicense: work.hasLicense,
            licenceNumber: work.licenseNumber,
            typeofwork: work.typeOfWork
        };

        const headers = { Authorization: `Bearer ${getToken()}` };

        try {
            // Post to Employee API
            await axios.post(EmployeeApiUrl, employeeData, { headers });

            // Delete from Work API
            await axios.delete(`${WorksApiUrl}/${work.id}`, { headers });

            // Update UI
            setWorks(works.filter(p => p.id !== work.id));

            // Show success message
            Swal.fire("Success!", "A new employee has been added successfully!", "success");
        } catch (error) {
            console.error("Error processing request:", error);
            Swal.fire("Error", "Something went wrong!", "error");
        } finally {
            setLoadingId(null); // Re-enable the button
        }
    };

    // Handle Reject
    const handleReject = (id) => {
        Swal.fire({
            title: "Are you sure?",
            text: "You won't be able to revert this!",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#d33",
            cancelButtonColor: "#3085d6",
            confirmButtonText: "Yes, delete it!"
        }).then((result) => {
            if (result.isConfirmed) {
                axios.delete(`${WorksApiUrl}/${id}`, { headers: { Authorization: `Bearer ${getToken()}` } })
                    .then(() => {
                        setWorks(works.filter(p => p.id !== id));
                        Swal.fire("Deleted!", "The record has been deleted.", "success");
                    })
                    .catch(error => console.error("Error deleting record:", error));
            }
        });
    };

    return (
        <div className="container py-2">
        {works.length === 0 ? (
            <p className="text-center text-gray-500 text-lg">No Requests available.</p>
        ) : (
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
                {works.map((work) => (
                    <div key={work.id} className="p-3 rounded-lg shadow-xl flex flex-col">
                        <div className="text-start">
                            <h2 className="text-xl font-semibold">{work.name}</h2>
                        </div>
                        <div className="py-3">
                            <p className="mb-2 text-gray-500"><strong>Email:</strong> {work.email}</p>
                            <p className="mb-2 text-gray-500"><strong>Phone:</strong> {work.phone}</p>
                            <p className="mb-2 text-gray-500"><strong>Address:</strong> {work.address}</p>
                            <p className="mb-2 text-gray-500"><strong>Driver’s License:</strong> {work.hasLicense}</p>
                            {work.hasLicense === "Yes" && (
                                <p className="mb-2 font-bold"><strong>License Number:</strong> {work.licenseNumber}</p>
                            )}
                            <p className="mb-2 text-sm"><strong>Type of Work:</strong> {work.typeOfWork.join(", ")}</p>
                        </div>
                        <div className="mt-3 flex justify-center gap-3">
                            <button
                                className="text-white bg-yellow-400 rounded-pill p-2 px-4"
                                onClick={() => handleAccept(work)}
                                disabled={loadingId === work.id}
                            >
                                {loadingId === work.id ? "Accepting..." : "Accept"}
                            </button>
                            <button
                                className="text-white bg-danger rounded-pill p-2 px-4"
                                onClick={() => handleReject(work.id)}
                                disabled={loadingId === work.id}
                            >
                                Reject
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        )}
    </div>
    
    );
};

export default WorkWithUs;