import React, { useState, useEffect } from "react";
import axios from "../../Https/Axios";
import { BookingsApiUrl, AllTasksApiUrl } from "../../Https/AdminSideAxiosUrls"
const Cleaning = () => {
    const [bookings, setBookings] = useState([]);
    const [selectedBooking, setSelectedBooking] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [showModal, setShowModal] = useState(false);
    const [deadline, setDeadline] = useState("");

    const fetchBookings = async () => {
        try {
            const response = await axios.get(BookingsApiUrl); // Replace with actual API URL
            setBookings(response.data);
            if (response.data.length > 0) {
                setSelectedBooking(response.data[0]); // Select the first booking by default
            }
            setLoading(false);
        } catch (error) {
            setError("Failed to fetch data. Please try again.");
            setLoading(false);
        }
    };
    useEffect(() => {
      

        fetchBookings();
    }, []);

    if (loading) return <p>Loading bookings...</p>;
    if (error) return <p>{error}</p>;




    const handleAddToTask = () => {
        setShowModal(true); // Modal ko open karo
    };

    const handleSubmitTask = async () => {
        if (!selectedBooking?._id || !deadline) {
            alert("Please select a deadline!");
            return;
        }
    
        const taskData = {
            bookingId: selectedBooking._id,
            deadline: deadline, // Sending deadline as a string
        };
    
        try {
            const token = localStorage.getItem("tchAdminToken");
    
            // Step 1: Add the task
            const response = await axios.post(AllTasksApiUrl, taskData, {
                headers: {
                    Authorization: `Bearer ${token}`, // Pass token in headers
                    "Content-Type": "application/json",
                },
            });
    
            // Step 2: Update booking status to "accepted"
            const updateBookingStatus = {
                status: "Accepted",
            };
    
            await axios.put(`${BookingsApiUrl}/${selectedBooking._id}`, updateBookingStatus, {
                headers: {
                    Authorization: `Bearer ${token}`,
                    "Content-Type": "application/json",
                },
            });
    
            alert("Task added successfully");
            fetchBookings();
            setShowModal(false); // Close modal
            setDeadline(""); // Clear deadline field
        } catch (error) {
            console.error("Error processing request:", error);
            alert("Failed to add task or update booking status!");
        }
    };
    


    return (
        <div className="container mx-auto">
            <div className="row">
                <div className="col-md-8">
                    {bookings.map((booking) => (
                        <div key={booking._id}
                        className={`border-2 rounded-lg bg-blue-100 bg-opacity-50 items-center p-2 flex mt-4 py-4 overflow-auto ${
                            selectedBooking?._id === booking._id ? 'border-yellow-600' : 'border-gray-300'
                        }`}
                        
                         onClick={() => setSelectedBooking(booking)}
                         >
                            <div>
                                <div className="flex-1 px-4"><strong>Name: </strong> {booking.name}</div>
                            </div>
                            <div>
                                <div className="flex-1 px-4 font-bold">Booking Date</div>
                                <div className="flex-1 px-4">{booking.bookingDate}</div>
                            </div>
                            <div>
                                <div className="flex-1 px-4 font-bold">Scheduled Time</div>
                                <div className="flex-1 px-4">{booking.scheduledTime}</div>
                            </div>
                            <div>
                                <div className="flex-1 px-4 font-bold text-center">Status</div>
                                <div className="flex-1 px-4">
                                    <span className={`px-2 py-1 rounded ${booking.status === "Completed" ? "text-green-500 font-bold" : "text-yellow-400 font-bold"}`}>
                                        {booking.status}
                                    </span>
                                </div>
                            </div>
                            <div>
                                <div className="flex px-4 gap-3 text-center items-center">
                                    <button onClick={() => setSelectedBooking(booking)} className="text-yellow-400">
                                        <i className="fas fa-eye text-2xl"></i>
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>

                <div className="col-md-4">
                    {selectedBooking && (
                        <div>
                            <div className="bg-white p-6 rounded-lg shadow-lg">
                                <h3 className="text-xl font-bold mb-2">Booking Details</h3>

                                <div className="border p-4 rounded-md shadow-md">
                                    <p className="mb-1"><strong>Name:</strong> {selectedBooking.name}</p>
                                    <p className="mb-1"><strong>Email:</strong> {selectedBooking.email}</p>
                                    <p className="mb-1"><strong>Phone:</strong> {selectedBooking.phone}</p>
                                    <p className="mb-1"><strong>Address:</strong> {selectedBooking.address}</p>
                                    <p className="mb-1"><strong>Booking Date:</strong> {selectedBooking.bookingDate}</p>
                                    <p className="mb-1"><strong>Scheduled Time:</strong> {selectedBooking.scheduledTime}</p>

                                    <h4 className="text-lg font-bold mt-4">Services:</h4>
                                    {selectedBooking.serviceData.map((service, index) => (
                                        <div key={index} className="border border-gray-200 p-3 mt-2 rounded-md">
                                            <p><strong>Service Type:</strong> {service.serviceType}</p>

                                            {service.serviceType === "Cleaning" && (
                                                <ul className="ml-4 list-none text-sm">
                                                    <li><strong>Cleaning Area:</strong> {service.cleaningArea}</li>
                                                    <li><strong>Cleaners:</strong> {service.cleaners}</li>
                                                    <li><strong>Square Meters:</strong> {service.squareMeters}</li>
                                                    <li><strong>Cleaner Cost:</strong> {service.cleanerCost}</li>
                                                    <li><strong>Total Cost:</strong> {service.totalCost}</li>
                                                </ul>
                                            )}

                                            {service.serviceType === "Helper" && (
                                                <ul className="ml-4 list-none text-sm">
                                                    <li><strong>Hours:</strong> {service.hours}</li>
                                                    <li><strong>Helpers:</strong> {service.helpers}</li>
                                                    <li><strong>Elevator:</strong> {service.elevator}</li>
                                                    <li><strong>Total Cost:</strong> {service.totalCost}</li>
                                                    <li><strong>Floor Cost:</strong> {service.floorCost}</li>
                                                    <li><strong>Total:</strong> {service.total}</li>
                                                </ul>
                                            )}

                                            {service.serviceType === "Transport" && (
                                                <ul className="ml-4 list-none text-sm">
                                                    <li><strong>From:</strong> {service.from}</li>
                                                    <li><strong>To:</strong> {service.to}</li>
                                                    <li><strong>Distance:</strong> {service.distance}</li>
                                                    <li><strong>Distance Cost:</strong> {service.distanceCost}</li>
                                                    <li><strong>Total:</strong> {service.total}</li>
                                                </ul>
                                            )}
                                        </div>
                                    ))}
                                    <p className="mt-3"><strong>Price:</strong> {selectedBooking.price}</p>
                                    {selectedBooking.status === "pending" && (
                                        <div className="flex justify-center gap-3 mt-3">
                                            <button className="bg-gray-500 text-white px-4 py-1 rounded-pill hover:bg-blue-600">
                                                Cancel
                                            </button>
                                            <button

                                                onClick={handleAddToTask}
                                                className="bg-yellow-400 text-white px-4 py-1 rounded-pill hover:bg-red-600">
                                                Add Task
                                            </button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}

                    {showModal && (
                        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
                            <div className="bg-white p-6 rounded-lg shadow-lg w-96">
                                <h2 className="text-lg font-semibold mb-4">Select Deadline</h2>
                                <input
                                    type="date"
                                    className="border p-2 w-full rounded-md"
                                    value={deadline}
                                    onChange={(e) => setDeadline(e.target.value)}
                                />
                                <div className="flex justify-end mt-4 gap-2">
                                    <button
                                        onClick={() => setShowModal(false)}
                                        className="bg-gray-400 text-white px-4 py-1 rounded-md hover:bg-gray-600"
                                    >
                                        Cancel
                                    </button>
                                    <button
                                        onClick={handleSubmitTask}
                                        className="bg-blue-500 text-white px-4 py-1 rounded-md hover:bg-blue-700"
                                    >
                                        Submit
                                    </button>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>
        </div>


    );
};

export default Cleaning;