// KlarnaPayForm.js
import React, { useState } from 'react';
import { useLocation } from "react-router-dom";
import axios from "../Https/Axios";
import { KlarnaPaymentApiUrl } from "../Https/UserSideAxiosUrls";
const KlarnaPayForm = () => {

    const location = useLocation();
      const totalCost = location.state?.totalCost;

  const [amount, setAmount] = useState(totalCost);
  const [klarnaHtml, setKlarnaHtml] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!amount) return;

    try {
      const response = await axios.post(KlarnaPaymentApiUrl, { amount: parseFloat(amount) });
      setKlarnaHtml(response.data.html_snippet);
    } catch (error) {
      console.error('Klarna error details:', {
        status: error?.response?.status,
        data: error?.response?.data,
        headers: error?.response?.headers,
      });
      
    }
  };

  return (
    <div className="max-w-xl mx-auto mt-40 p-6 bg-white shadow-lg rounded-lg">
      <h3 className="text-2xl font-semibold mb-4 text-gray-800">Pay with Klarna</h3>
      <form onSubmit={handleSubmit} className="space-y-4">
        <div>
          <label className="block mb-1 text-gray-700 font-medium">Amount (USD):</label>
          <input
            type="number"
            min="1"
            step="0.01"
            className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            readOnly
            required
          />
        </div>
        <button
          type="submit"
          className="w-full bg-yellow-400 text-white py-2 rounded-lg hover:bg-yellow-400 transition duration-300"
        >
          Proceed to Pay
        </button>
      </form>

      {klarnaHtml && (
        <div className="mt-6" dangerouslySetInnerHTML={{ __html: klarnaHtml }} />
      )}
    </div>
  );
};

export default KlarnaPayForm;