"use client";

import React, { useState } from "react";
import { useTranslation } from "react-i18next";
// import PartnerForm from "../_components/partnersForm";
// import CustomModal from "../_components/SuccessModal";
import PartnerForm from "./partnersForm";
import bg_image from "../../assets/BeAPartner/bg_image.jpg"
export default function BeOurPartner() {
  const { t } = useTranslation();
  const [isModalOpen, setIsModalOpen] = useState(false);

  return (
    <div className="">
      <div className="relative z-0 flex-col flex items-center justify-center w-full max-md:px-5 max-md:pt-24 max-md:pb-28 max-md:max-w-full">
        <img
          src={bg_image}
          alt="banner"
          className="object-cover -z-10 absolute inset-0 size-full"
        />
        <div className="object-cover z-10 absolute inset-0 size-full bg-[#0d0c0c9c]"></div>

        <div className="flex flex-col mt-36 items-center justify-center text-3xl md:text-5xl lg:text-6xl xl:text-7xl z-30 font-bold">
          <h1 data-aos="fade-down" className="text-6xl font-bold text-sky-800 leading-[73px] max-md:max-w-full max-md:text-4xl max-md:leading-[58px]">
            <span className="text-white">{t("partner.banner_title_part1")}{" "}</span>
            <span className="text-[#1CAC78]">{t("partner.banner_title_part2")}{" "}</span>
            <span className="text-white">{t("partner.banner_title_part3")}</span>
          </h1>

          <p className="text-xl text-white max-w-3xl mx-auto mb-8 font-normal">
            {t("partner.banner_description")}
          </p>
        </div>

        <div className="flex rounded-2xl relative  my-4 mb-20 z-20 w-full items-center justify-center" data-aos="fade-up">
          <PartnerForm setIsModalOpen={setIsModalOpen} />
        </div>
      </div>

      {/* <CustomModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        heading={t("partner.form_success_heading")}
        description={t("partner.form_success_description")}
      /> */}
    </div>
  );
}
