import { Link } from "react-router-dom";
import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import img1 from "../../assets/Processes/process_1.png";
import img2 from "../../assets/Processes/process_2.png";
import img3 from "../../assets/Processes/process_3.png";
import img4 from "../../assets/Processes/process_4.png";

const ProcessSection = () => {
    const { t } = useTranslation();
    const [activeIndex, setActiveIndex] = useState(0);

    const processSteps = t("process_steps", { returnObjects: true });

    // Array of images corresponding to process steps
    const images = [img1, img2, img3, img4];

    return (
        <div className="flex flex-col xl:px-20 px-5 mt-20">
            <div className="flex flex-wrap gap-10 items-end w-full uppercase max-md:max-w-full">
                <div className="flex flex-col flex-1 shrink basis-0 min-w-[240px] max-md:max-w-full">
                    <div data-aos="fade-right" className="flex flex-wrap gap-6 items-center w-full text-xl sm:text-2xl font-bold text-emerald-500 tracking-[5.52px] max-md:max-w-full">
                        <div className="shrink-0 self-stretch my-auto h-0.5 border-2 border-emerald-500 border-solid w-[50px] sm:w-[86px]" />
                        <div className="self-stretch my-auto">{t("our_process")}</div>
                    </div>
                    <div data-aos="fade-up-right" className="mt-4 text-3xl sm:text-4xl font-semibold text-black w-full">
                        <span className="font-bold text-neutral-800">{t("our")} </span>
                        <span className="font-bold text-sky-800">{t("process")}</span>
                    </div>
                </div>
                <div className="hidden md:flex sm:flex shrink-0 h-[49px] w-[206px]" />
            </div>
            <div className="px-px sm:mt-16">
                <div className="flex gap-5 flex-col-reverse lg:flex-row w-full items-center justify-center">
                    <div className="lg:flex flex-col hidden lg:w-6/12 max-md:ml-0 w-full">
                        <div className="flex flex-col w-full max-md:max-w-full">
                            <div className="flex flex-col w-full rounded-md max-md:max-w-full">
                                <img
                                    loading="lazy"
                                    src={images[activeIndex]} // Image changes dynamically
                                    alt="Process Step"
                                    className="h-[300px] w-full rounded-xl aspect-[1.24] max-md:max-w-full"
                                />
                            </div>
                            <div className="flex flex-col mt-5 w-full max-md:max-w-full">
                                <div className="text-2xl lg:text-4xl  font-bold text-neutral-800 max-md:max-w-full">
                                    {processSteps[activeIndex]?.title}
                                </div>
                                <div className="mt-4 text-base text-justify text-zinc-800 max-md:max-w-full">
                                    {processSteps[activeIndex]?.description}
                                </div>
                            </div>
                            <Link to="book-now">
                                <button className="gap-2.5 mt-5 self-stretch hover:scale-105 transition-all duration-250 px-9 py-3.5 my-auto sm:w-48 text-white rounded border border-[#1CAC78] bg-[#1CAC78] border-solid min-h-[46px] max-md:px-5">
                                    {t("about.bookNow")}
                                </button>
                            </Link>
                        </div>
                    </div>
                    <div className="flex flex-col ml-5 lg:w-6/12 max-md:ml-0 w-full">
                        <div className="flex relative flex-col text-zinc-800 max-md:mt-10 max-md:max-w-full">
                            <div className="flex z-0 flex-col w-full lg:max-w-[638px] max-w-full">
                                {processSteps.map((step, index) => (
                                    <div
                                        key={index}
                                        className={`cursor-pointer my-1 rounded-lg transition-all 
                           ${activeIndex === index ? "border-emerald-500 bg-white shadow-lg" : "border border-gray-300"}`}
                                        onClick={() => setActiveIndex(index)}
                                    >
                                        <ProcessCard
                                            {...step}
                                            imgSrc={images[index]}
                                            isActive={activeIndex === index}
                                        />
                                    </div>
                                ))}
                            </div>
                        </div>

                    </div>
                </div>
            </div>
        </div>
    );
};

const ProcessCard = ({ title, description, imgSrc, isActive }) => {
    return (
        <div className="flex items-center gap-4 p-3 rounded-lg transition-all duration-300 "
        >
            {/* Process Image */}
            {/* <img
                src={imgSrc}
                alt="Process Step"
                className={`w-24 h-24 rounded-md transition-all duration-300 ${isActive ? "opacity-100 scale-105" : "opacity-70"}`}
            /> */}

            {/* Process Text */}
            <div className="flex flex-col">
                <div className="text-xl font-bold">{title}</div>
                {/* <div className={`mt-1 leading-normal ${isActive ? "text-black" : "text-gray-500 hidden lg:block"}`}>
                    {description}
                </div> */}
            </div>
        </div>
    );
};


export default ProcessSection;
