import React from "react";
import { useTranslation } from "react-i18next";
import img from "../../assets/aboutus/bottomsectiontwo.jpg"
const BottomSectionTwo = () => {
  const { t } = useTranslation();

  return (
    <section className="py-24 relative xl:mr-0 lg:mr-5 mr-0">
      <div className="w-full max-w-7xl px-4 md:px-5 lg:px-5 mx-auto">
        <div className="w-full justify-start items-center xl:gap-12 gap-10 grid lg:grid-cols-2 grid-cols-1">
          <div className="w-full lg:justify-start justify-center items-start flex">
            <div className="sm:w-[564px] w-full sm:h-[646px] h-full sm:bg-gray-100 rounded-3xl sm:border border-gray-200 relative">
              <img
                className="sm:mt-5 sm:ml-5 w-full h-full rounded-3xl object-cover"
                src={img}
                alt="about Us image"
              />
            </div>
          </div>
          <div className="w-full flex-col justify-center lg:items-start items-center gap-10 inline-flex">
            <div className="w-full flex-col justify-center items-start gap-8 flex">
              <div className="flex-col justify-start lg:items-start items-center gap-4 flex">
                <div className="w-full flex-col justify-start lg:items-start items-center gap-3 flex">
                  <div className="flex flex-col w-full font-bold uppercase max-md:max-w-full">
                    <div
                      data-aos="fade-right"
                      className="flex flex-wrap gap-6 items-center w-full text-lg sm:text-xl leading-none text-sky-800 tracking-[5.52px] max-md:max-w-full"
                    >
                      <div className="h-[2px] rounded-md my-auto bg-[#1CAC78] w-[70px] sm:w-[115px]" />
                      <div className="self-stretch text-[#1CAC78] my-auto">
                        {t("bottomsectiontwo.section_title")}
                      </div>
                    </div>
                    <div
                      data-aos="fade-down"
                      className="mt-4 text-3xl sm:text-4xl leading-10 text-gray-900 max-md:max-w-full"
                    >
                      {t("bottomsectiontwo.main_heading").split("\n").map((line, index) => (
                        <React.Fragment key={index}>
                          {line}
                          <br />
                        </React.Fragment>
                      ))}
                    </div>
                  </div>
                  <p className="text-gray-500 text-base font-normal leading-relaxed lg:text-start text-center">
                    {t("bottomsectiontwo.description")}
                  </p>
                </div>
              </div>
              <div className="w-full flex-col justify-center items-start gap-6 flex">
                <div className="w-full justify-start items-center gap-8 grid md:grid-cols-2 grid-cols-1">
                  <div className="w-full h-full p-3.5 rounded-xl border border-gray-200 hover:border-gray-400 transition-all duration-700 ease-in-out flex-col justify-start items-start gap-2.5 inline-flex">
                    <h4 className="text-gray-900 text-2xl font-bold font-manrope leading-9">
                      {t("bottomsectiontwo.years_experience")}
                    </h4>
                    <p className="text-gray-500 text-base font-normal leading-relaxed">
                      {t("bottomsectiontwo.years_experience_desc")}
                    </p>
                  </div>
                  <div className="w-full h-full p-3.5 rounded-xl border border-gray-200 hover:border-gray-400 transition-all duration-700 ease-in-out flex-col justify-start items-start gap-2.5 inline-flex">
                    <h4 className="text-gray-900 text-2xl font-bold font-manrope leading-9">
                      {t("bottomsectiontwo.customers_served")}
                    </h4>
                    <p className="text-gray-500 text-base font-normal leading-relaxed">
                      {t("bottomsectiontwo.customers_served_desc")}
                    </p>
                  </div>
                </div>
                <div className="w-full h-full justify-start items-center gap-8 grid md:grid-cols-2 grid-cols-1">
                  <div className="w-full p-3.5 rounded-xl border border-gray-200 hover:border-gray-400 transition-all duration-700 ease-in-out flex-col justify-start items-start gap-2.5 inline-flex">
                    <h4 className="text-gray-900 text-2xl font-bold font-manrope leading-9">
                      {t("bottomsectiontwo.locations")}
                    </h4>
                    <p className="text-gray-500 text-base font-normal leading-relaxed">
                      {t("bottomsectiontwo.locations_desc")}
                    </p>
                  </div>
                  <div className="w-full h-full p-3.5 rounded-xl border border-gray-200 hover:border-gray-400 transition-all duration-700 ease-in-out flex-col justify-start items-start gap-2.5 inline-flex">
                    <h4 className="text-gray-900 text-2xl font-bold font-manrope leading-9">
                      {t("bottomsectiontwo.stress_free")}
                    </h4>
                    <p className="text-gray-500 text-base font-normal leading-relaxed">
                      {t("bottomsectiontwo.stress_free_desc")}
                    </p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default BottomSectionTwo;
