import React from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import first from "../../assets/aboutus/first.jpg"
// import AboutUs from "../_components/AboutUs";
// import ServicesMain from "../_components/ServicesMain";
// import ServicesSlider from "../_components/ServicesSlider";
import cleaning from "../../assets/aboutus/cleaning.jpg"
import transport from "../../assets/aboutus/transport.jpg"
import moving from "../../assets/aboutus/moving.jpg"
import ServicesSlider from "./ServiceSlider";
import Section from "./BottomSection";
import BottomSectionTwo from "./BottomSectionTwo";
import BottomSectionThree from "./BottomSectionThree";
import LocationArea from "./LocationArea";
function AboutUsMain() {
  const { t } = useTranslation();
  const features = t("aboutus.features", { returnObjects: true });

  if (!Array.isArray(features)) {
    console.error("Features is not an array:", features);
  }
  return (
    <>
      <section className="px-12 about-section py-24 mt-10">
        <div>
          <div className="row">
            {/* Content Column */}
            <div className="col-md-6">
              <div className="inner-column lg:pl-8">
                <div className="flex flex-col w-full font-bold uppercase max-md:max-w-full">
                  <div data-aos="fade-right" className="flex flex-wrap gap-6 items-center w-full text-xl sm:text-2xl leading-none text-sky-800 tracking-[5.52px]">
                    <div className="h-[2px] rounded-md my-auto bg-[#1CAC78] w-[70px] sm:w-[115px]" />
                    <div className="self-stretch text-[#1CAC78] my-auto">{t("aboutus.aboutUs.heading")}</div>
                  </div>
                  <div data-aos="fade-down" className="mt-4 text-3xl sm:text-4xl leading-10 text-gray-900">
                    {t("aboutus.aboutUs.subHeading")}
                  </div>
                </div>
                <p className="text-gray-500 text-base leading-relaxed my-8">
                  {t("aboutus.aboutUs.description")}
                </p>

                {/* Features List */}
                <ul className="list-disc pl-5 text-gray-700 list-none">
                  {Array.isArray(features) &&
                    features.map((feature, index) => (
                      <li key={index} className="mb-2 text-lg">&#10004; {feature}</li>
                    ))}
                </ul>
              </div>
            </div>

            {/* Image Column */}
            <div className="col-md-6">
              <img src={first} className="rounded-xl h-auto" />
            </div>
          </div>
        </div>
      </section>



      {/* <ServicesMain />
      <AboutUs />
      <ServicesSlider /> */}

      <section className="px-12 md:py-24 lg:py-24 lg:mt-10 md:mt-10">
        <div>
          <div className="row items-center">
            <div className="col-md-6">
              <h1 className="text-4xl mb-4 font-bold text-black">
                {t("aboutus.services.title")}
              </h1>
              <p className="text-gray-500 mb-4 text-xl">{t("aboutus.services.description")}</p>

              <div className="mb-4">
                <div>
                  <p className="text-xl">{t("aboutus.stats.yearsExperience")}</p>
                </div>
                <div>
                  <p className="text-xl">{t("aboutus.stats.customersServed")}</p>
                </div>
                <div>
                  <p className="text-xl">{t("aboutus.stats.serviceLocations")}</p>
                </div>
              </div>

              <Link href="/book-now">
                <button className="gap-2.5 md:mb-0 lg:mb-0 mb-10 hover:scale-105 transition-all duration-250 px-10 w-60 py-4 text-white rounded border border-[#1CAC78] bg-[#1CAC78]">
                  {t("aboutus.buttons.bookNow")}
                </button>
              </Link>
            </div>
            <div className="col-md-6">
              <img src={cleaning} className="rounded-xl" />
            </div>
          </div>
        </div>
      </section>

      <section className="px-12 md:py-24 lg:py-24  mt-10">
        <div>
          <div className="row items-center">
            <div className="col-md-6 md:mb-0 lg:mb-0 mb-10">
              <img src={transport} className="rounded-xl" />
            </div>
            <div className="col-md-6">
              <h1 className="text-3xl md:text-4xl  lg:text-4xl  mb-4  font-bold text-black">
                {t("aboutus.transportservices.title")}
              </h1>
              <p className="text-gray-500 mb-4 text-xl">{t("aboutus.transportservices.description")}</p>

              <div className="mb-4">
                <div>
                  <p className="text-xl">{t("aboutus.transportstats.yearsExperience")}</p>
                </div>
                <div>
                  <p className="text-xl">{t("aboutus.transportstats.customersServed")}</p>
                </div>

              </div>

              <Link href="/book-now">
                <button className="gap-2.5 hover:scale-105 transition-all duration-250 px-10 w-60 py-4 text-white rounded border border-[#1CAC78] bg-[#1CAC78]">
                  {t("aboutus.transportbuttons.bookNow")}
                </button>
              </Link>
            </div>

          </div>
        </div>
      </section>


      <section className="px-12 md:py-24 lg:py-24  mt-10">
        <div>
          <div className="row items-center">
          <div className="col-md-6 md:mb-0 lg:mb-0 mb-10">
              <h1 className="text-4xl mb-4 font-bold text-black">
                {t("aboutus.movingservices.title")}
              </h1>
              <p className="text-gray-500 mb-4 text-xl">{t("aboutus.movingservices.description")}</p>

              <div className="mb-4">
                <div>
                  <p className="text-xl">{t("aboutus.movingstats.yearsExperience")}</p>
                </div>
                <div>
                  <p className="text-xl">{t("aboutus.movingstats.customersServed")}</p>
                </div>
                <div>
                  <p className="text-xl">{t("aboutus.movingstats.serviceLocations")}</p>
                </div>
              </div>

              <Link href="/book-now">
                <button className="gap-2.5 hover:scale-105 transition-all duration-250 px-10 w-60 py-4 text-white rounded border border-[#1CAC78] bg-[#1CAC78]">
                  {t("aboutus.movingbuttons.bookNow")}
                </button>
              </Link>
            </div>
            <div className="col-md-6">
              <img src={moving} className="rounded-xl" />
            </div>
          </div>
        </div>
      </section>

      <ServicesSlider />
      <Section />
      <BottomSectionTwo />
      <BottomSectionThree />
      <LocationArea/>
    </>
  );
}

export default AboutUsMain;
