import { useState } from "react";
import axios from "../../Https/Axios";
import { PartnerApiUrl } from "../../Https/AdminSideAxiosUrls"
import { toast } from "react-toastify";

const AddPartner = () => {
  const [partner, setPartner] = useState({
    name: "",
    email: "",
    phone: "",
    vehicleNumber: "",
    licenseNumber: "",
    vansCount: "",
    transportPermit: "",
    liabilityInsurance: ""
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setPartner({ ...partner, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const requestData = {
      ...partner,
      transportPermit: partner.transportPermit === "Yes",
      liabilityInsurance: partner.liabilityInsurance === "Yes",
      vans: Number(partner.vansCount)
    };

    try {
      const response = await axios.post(PartnerApiUrl, requestData, {
        headers: {
          "Content-Type": "application/json",
        },

      });
      alert("Partner added successfully!");      // toast.success("Partner added successfully!");
      console.log("Response:", response.data);

      // Reset form
      setPartner({
        name: "",
        email: "",
        phone: "",
        vehicleNumber: "",
        licenseNumber: "",
        vansCount: "",
        transportPermit: "",
        liabilityInsurance: ""
      });
    } catch (error) {
      toast.error("Failed to add partner");
      console.error("Error:", error);
    }
  };

  return (
    <div className="mx-auto bg-white p-8 shadow-xl rounded-lg mt-8 border border-gray-200">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {[
            { label: "Name", type: "text", name: "name" },
            { label: "Email", type: "email", name: "email" },
            { label: "Phone", type: "tel", name: "phone" },
            { label: "Vehicle Number", type: "text", name: "vehicleNumber" },
            { label: "License Number", type: "text", name: "licenseNumber" },
            { label: "How many vans", type: "number", name: "vansCount" }
          ].map(({ label, type, name }, index) => (
            <div key={index}>
              <label className="block text-gray-600 font-medium mb-1">{label}</label>
              <input
                type={type}
                name={name}
                value={partner[name]}
                onChange={handleChange}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring focus:ring-blue-300 bg-gray-50"
              />
            </div>
          ))}

          {[
            { label: "Do you have a transport permit?", name: "transportPermit" },
            { label: "Do you have liability insurance?", name: "liabilityInsurance" }
          ].map(({ label, name }, index) => (
            <div key={index}>
              <label className="block text-gray-600 font-medium mb-1">{label}</label>
              <select
                name={name}
                value={partner[name]}
                onChange={handleChange}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring focus:ring-blue-300 bg-gray-50"
              >
                <option value="">Select</option>
                <option value="Yes">Yes</option>
                <option value="No">No</option>
              </select>
            </div>
          ))}
        </div>

        <div className="text-end mt-4">
          <button
            type="submit"
            className="bg-yellow-400 text-black px-12 py-3 rounded-lg hover:bg-yellow-400 transition text-lg font-medium"
          >
            Add Partner
          </button>
        </div>
      </form>
    </div>
  );
};

export default AddPartner;