import React, { useState, useEffect } from "react";
import { FaChevronDown, FaFacebook, FaInstagram, FaEnvelope, FaBars, FaPhone, FaTimes } from "react-icons/fa";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import logo from "../../assets/logo_new.png"
const NavigationBar = () => {
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [dropDown, setDropDown] = useState(false);
    const currentPath = window.location.pathname;

    useEffect(() => {
        setSidebarOpen(false);
    }, [currentPath]);

    const { t, i18n } = useTranslation();

    const changeLanguage = (event) => {
        i18n.changeLanguage(event.target.value);
    };

    return (
        <div className="fixed top-0 w-full z-50">
            {/* Top Bar */}
            <section className="bg-sky-800 text-white py-2">
                <div className="container mx-auto flex justify-between items-center px-4">
                    <div className="flex space-x-6">
                        <a href="tel:+46735980956" className="hidden md:flex items-center space-x-2 hover:text-gray-300 transition">
                            <FaPhone size={16} />
                            <span>{t("navbar.phone")}</span>
                        </a>
                        <a href="mailto:info@forarer.se" className="flex items-center space-x-2 hover:text-gray-300 transition">
                            <FaEnvelope size={16} />
                            <span>{t("navbar.email")}</span>
                        </a>
                    </div>
                    <div className="flex space-x-4">
                        <a href="https://m.facebook.com/100076726356313/" className="hover:text-gray-300 transition">
                            <FaFacebook size={16} />
                        </a>
                        <a href="https://www.instagram.com/_forareakuten_?igsh=MXJqZHJ4MWhocTNleA==" className="hover:text-gray-300 transition">
                            <FaInstagram size={16} />
                        </a>
                    </div>
                </div>
            </section>

            {/* Main Navigation */}
            <div className="bg-white shadow-md py-4 px-6 flex justify-between items-center w-full lg:w-11/12 lg:rounded-br-[200px]">

                {/* Logo */}
                <Link to="/">
                    <img src={logo} className="w-32" alt="Logo" />
                </Link>

                {/* Desktop Menu */}
                <div className="hidden lg:flex items-center space-x-6 text-black font-medium ">
                    <Link to="/" className={`hover:text-sky-800 transition ${currentPath === "/" ? "text-sky-800 font-bold" : ""}`}>
                        {t("navbar.home")}
                    </Link>
                    <div
                        className="relative group"
                        onMouseLeave={() => setDropDown(false)}  // 👈 Add this line
                    >
                        <Link to="/book-service">
                            <button
                                onMouseEnter={() => setDropDown(true)} // 👈 Only show on hover
                                className="flex items-center gap-x-2 hover:text-sky-800 transition"
                            >
                                {t("navbar.services")}
                                <FaChevronDown className="h-4 w-4" />
                            </button>
                        </Link>

                        {dropDown && (
                            <div className="absolute left-0 w-48 bg-white shadow-md rounded-md border overflow-hidden transition-opacity duration-200">
                                <Link to="/book-service" className="block px-4 py-2 hover:bg-gray-100 transition">
                                    {t("navbar.transport")}
                                </Link>
                                <Link to="/book-service" className="block px-4 py-2 hover:bg-gray-100 transition">
                                    {t("navbar.cleaning")}
                                </Link>
                                <Link to="/book-service" className="block px-4 py-2 hover:bg-gray-100 transition">
                                    {t("navbar.moving_help")}
                                </Link>
                            </div>
                        )}
                    </div>

                    <Link to="/about-us" className={`hover:text-sky-800 transition ${currentPath === "/about-us" ? "text-sky-800 font-bold" : ""}`}>
                        {t("navbar.about_us")}
                    </Link>
                    <Link to="/partner" className={`hover:text-sky-800 transition ${currentPath === "/partner" ? "text-sky-800 font-bold" : ""}`}>
                        {t("navbar.become_partner")}
                    </Link>
                    <Link to="/work" className={`hover:text-sky-800 transition ${currentPath === "/work" ? "text-sky-800 font-bold" : ""}`}>
                        {t("navbar.work_with_us")}
                    </Link>

                    <Link to='/get-offer'>
                        <button
                            style={{ textWrap: "nowrap" }}
                            className='px-6 py-2 text-white bg-sky-800 rounded-full hover:scale-105 transition-all duration-250 hover:bg-sky-900'>
                            {t('hero.Get an offer')}
                        </button>
                    </Link>
                    <Link to='/book-service'>
                        <button
                            style={{ textWrap: "nowrap" }}
                            className='px-6 py-2 text-white bg-[#1CAC78] rounded-full  hover:scale-105 transition-all duration-250 hover:bg-emerald-600'>
                            {t('hero.Book now')}
                        </button>
                    </Link>
                </div>

                {/* Language Selector */}
                <select
                    onChange={changeLanguage}
                    className="bg-white text-black border border-gray-300 px-2 py-1 lg:me-10 rounded focus:outline-none focus:ring focus:ring-sky-300"
                >
                    <option value="ur">Norsk</option>
                    <option value="en">English</option>
                    <option value="sv">Sweedish</option>

                </select>

                {/* Mobile Menu Button */}
                <div className="lg:hidden">
                    <button onClick={() => setSidebarOpen(!sidebarOpen)}>
                        <FaBars className="h-6 w-6" />
                    </button>
                </div>
            </div>

            {/* Mobile Sidebar */}
            {/* Mobile Sidebar */}
            {sidebarOpen && (
                <div className="fixed top-0 right-0 w-64 h-full bg-white shadow-lg z-50 p-5 flex flex-col items-start transition-transform duration-300">
                    <button onClick={() => setSidebarOpen(false)} className="self-end mb-4">
                        <FaTimes className="h-6 w-6" />
                    </button>
                    <Link to="/" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                        {t("navbar.home")}
                    </Link>
                    <div className="w-full">
                        <button
                            onMouseEnterEnter={() => setDropDown(!dropDown)}
                            className="flex justify-between w-full text-lg py-2 hover:text-sky-800"
                        >
                            {t("navbar.services")}
                            <FaChevronDown className={`h-4 w-4 transform ${dropDown ? "rotate-180" : ""}`} />
                        </button>
                        {dropDown && (
                            <div className="pl-4">
                                <Link to="/book-service" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                                    {t("navbar.transport")}
                                </Link>
                                <Link to="/book-service" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                                    {t("navbar.cleaning")}
                                </Link>
                                <Link to="/book-service" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                                    {t("navbar.moving_help")}
                                </Link>
                            </div>
                        )}
                    </div>
                    <Link to="/about-us" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                        {t("navbar.about_us")}
                    </Link>
                    <Link to="/partner" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                        {t("navbar.become_partner")}
                    </Link>
                    <Link to="/work" className="block py-2 text-lg hover:text-sky-800" onClick={() => setSidebarOpen(false)}>
                        {t("navbar.work_with_us")}
                    </Link>
                </div>
            )}

        </div>
    );
};

export default NavigationBar;