import React, { useState, useEffect } from "react";
import { Modal, Button, Form } from "react-bootstrap";
import axios from "../../Https/Axios";
import { TasksApiUrl, EmployeeApiUrl, AllTasksApiUrl, PartnerApiUrl } from "../../Https/AdminSideAxiosUrls";
import Swal from "sweetalert2";

const getToken = () => localStorage.getItem("tchAdminToken");


const PendingTaskCard = ({ task, fetchTasks }) => {
    const [showDetails, setShowDetails] = useState(false);
    const [showAssign, setShowAssign] = useState(false);
    const [showAssignPartners, setShowAssignPartners] = useState(false);
    const [selectedEmployees, setSelectedEmployees] = useState([]);
    const [selectedPartners, setSelectedPartners] = useState([]);
    const [show, setShow] = useState(false);
    const [showPartners, setShowPartners] = useState(false);
    const handleClose = () => setShow(false);
    const handleShow = () => setShow(true);
    const handleCloseDetails = () => setShowDetails(false);
    const handleShowDetails = () => setShowDetails(true);
    const handleCloseAssign = () => setShowAssign(false);
    const handleShowAssign = () => setShowAssign(true);
    const handleCloseAssignPartners = () => setShowAssignPartners(false);
    const handleShowAssignPartners = () => setShowAssignPartners(true);
    const handleEmployeeSelect = (id) => {
        setSelectedEmployees((prevSelected) =>
            prevSelected.includes(id)
                ? prevSelected.filter((empId) => empId !== id)
                : [...prevSelected, id]
        );
    };

    const handlePartnersSelect = (id) => {
        setSelectedPartners((prevSelected) =>
            prevSelected.includes(id)
                ? prevSelected.filter((partnerId) => partnerId !== id)
                : [...prevSelected, id]
        );
    };



    const [selectedTaskId, setSelectedTaskId] = useState(null);


    const handleAssign = async () => {


        try {

            // Define API URL (Replace with your actual endpoint)
            const apiUrl = `${AllTasksApiUrl}/${selectedTaskId}`;

            // Prepare payload
            const payload = {
                assignedToEmployees: selectedEmployees,
                status: "inprogress",

            };

            // Send PUT request
            const response = await axios.put(apiUrl, payload, {
                headers: { Authorization: `Bearer ${getToken()}` },

            });

            // Success message
            alert("updated")
            fetchTasks();
            // Close the modal or dialog
            handleCloseAssign();
        } catch (error) {
            console.error('Error assigning task:', error);
        }
    };


    const handleAssignToPartners = async () => {


        try {

            // Define API URL (Replace with your actual endpoint)
            const apiUrl = `${AllTasksApiUrl}/${selectedTaskId}`;

            // Prepare payload
            const payload = {
                assignedToPartners: selectedPartners,
                status: "inprogress",

            };

            // Send PUT request
            const response = await axios.put(apiUrl, payload, {
                headers: { Authorization: `Bearer ${getToken()}` },

            });

            // Success message
            alert("updated")
            fetchTasks();
            // Close the modal or dialog
            handleCloseAssign();
        } catch (error) {
            console.error('Error assigning task:', error);
        }
    };

    

    const [employees, setEmployees] = useState([]);
    const [partners, setPartners] = useState([]);

    useEffect(() => {
        fetchEmployees();
        fetchpartners();
    }, []);

    const fetchEmployees = async () => {
        try {
            const response = await axios.get(EmployeeApiUrl, {
                headers: { Authorization: `Bearer ${getToken()}` },
            });
            setEmployees(response.data);
        } catch (error) {
            console.error("Error fetching employees:", error);
        }
    };


    const fetchpartners = async () => {
        try {
            const response = await axios.get(PartnerApiUrl, {
                headers: { Authorization: `Bearer ${getToken()}` },
            });
            console.log(response)
            setPartners(response.data.partners);
        } catch (error) {
            console.error("Error fetching partners:", error);
        }
    };

    const handleDelete = async (id) => {
        Swal.fire({
            title: "Are you sure?",
            text: "Are you sure you want to delete? If Yes, then it will be deleted permanently!",
            icon: "warning",
            showCancelButton: true,
            confirmButtonColor: "#d33",
            cancelButtonColor: "#3085d6",
            confirmButtonText: "Yes, delete it!",
        }).then(async (result) => {
            if (result.isConfirmed) {
                try {
                    await axios.delete(`${AllTasksApiUrl}/${id}`, {
                        headers: { Authorization: `Bearer ${getToken()}` },
                    });


                    Swal.fire("Deleted!", "Task has been deleted.", "success");
                    fetchTasks();

                } catch (error) {
                    console.error("Error deleting Task:", error);
                    Swal.fire("Error!", "Failed to delete Task.", "error");
                }
            }
        });
    };

    return (
        <div className="flex flex-wrap items-center justify-between w-full p-4 bg-white shadow-lg rounded-lg border border-gray-200  ">
            {/* Task Details */}
            <div className="bg-yellow-400 p-2 px-3 rounded-circle text-2xl">
                <i className="fas fa-tasks"></i>
            </div>
            <div className="flex flex-col flex-grow mx-md-4  pb-2  my-md-0 my-3">
                <div className="flex flex-wrap justify-between items-center">
                    <h3 className="text-lg font-semibold">{task.name}</h3>
                    <div className="flex gap-3 items-center ">
                        <i className="fas fa-eye text-white bg-danger p-2 rounded-circle" onClick={handleShow}></i>
                        <i className="fas fa-trash text-white bg-yellow-400 p-2 rounded-circle" onClick={() => handleDelete(task.id)}></i>
                        <Button className="rounded-full px-3 bg-yellow-400 border-0" size="sm"
                            onClick={() => {
                                setSelectedTaskId(task.id);
                                handleShowAssign();
                            }}>
                            Assign to Employees
                        </Button>
                        <Button 
                        
                        className="rounded-full px-3 bg-yellow-400 border-0" size="sm"
                        
                        onClick={() => {
                            setSelectedTaskId(task.id);
                            handleShowAssignPartners();
                        }}                        
                        >Assign to Partners</Button>

                    </div>
                </div>
                <div className="bg-blue-300 bg-opacity-75 p-2 mt-2 rounded-full"></div>
            </div>
            <div className="text-gray-600 text-sm">
                <p className="p-0 m-0 font-bold text-yellow-400">Deadline</p>
                <p className="p-0 m-0">{task.deadline}</p>
            </div>

            {/* Assign Modal */}
            <Modal show={showAssign} onHide={handleCloseAssign} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Assign Employees</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form>
                        {employees.map((employee) => {
                            // Define colors based on availability status


                            return (
                                <div key={employee._id} className="d-flex justify-content-between align-items-center mb-2 p-2 border rounded">
                                    <div >
                                        <Form.Check
                                            type="checkbox"
                                            label={employee.name}
                                            checked={selectedEmployees.includes(employee._id)}
                                            onChange={() => handleEmployeeSelect(employee._id)}
                                        />

                                    </div>

                                    <p className="text-gray-600"> {employee.typeofwork.join(", ")}</p>

                                </div>
                            );
                        })}
                    </Form>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={handleCloseAssign}>Close</Button>
                    <Button className="bg-yellow-400 border-0" onClick={handleAssign} disabled={selectedEmployees.length === 0}>
                        Assign Task
                    </Button>
                </Modal.Footer>
            </Modal>

            <Modal show={showAssignPartners} onHide={handleCloseAssignPartners} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Assign Partners</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <Form>
                        {partners.map((partner) => {

                            return (
                                <div key={partner._id} className="d-flex justify-content-between align-items-center mb-2 p-2 border rounded">
                                    <div >
                                        <Form.Check
                                            type="checkbox"
                                            label={partner.name}
                                            checked={selectedPartners.includes(partner._id)}
                                            onChange={() => handlePartnersSelect(partner._id)}
                                        />

                                    </div>


                                </div>
                            );
                        })}
                    </Form>
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={handleCloseAssignPartners}>Close</Button>
                    <Button className="bg-yellow-400 border-0" onClick={handleAssignToPartners} disabled={selectedPartners.length === 0}>
                        Assign Task
                    </Button>
                </Modal.Footer>
            </Modal>


            <Modal show={show} onHide={handleClose} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Task Details</Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <p><strong>Name:</strong> {task.name}</p>
                    <p><strong>Email:</strong> {task.email}</p>
                    <p><strong>Phone:</strong> {task.phone}</p>
                    <p><strong>Address:</strong> {task.address}</p>
                    <p><strong>Price:</strong> {task.price}</p>

                    <h5 className="mt-3">Service Details:</h5>
                    {task.serviceData.map((service, index) => (
                        <div key={index} className="border p-2 mb-2 rounded">
                            <p><strong>Type:</strong> {service.serviceType}</p>

                            {/* Transport Service Details */}
                            {service.serviceType === "Transport" && (
                                <>
                                    <p><strong>From:</strong> {service.from}</p>
                                    <p><strong>To:</strong> {service.to}</p>
                                    <p><strong>Distance:</strong> {service.distance}</p>
                                    <p><strong>Cost:</strong> {service.distanceCost}</p>
                                    <p><strong>Total:</strong> {service.total}</p>
                                </>
                            )}

                            {/* Helper Service Details */}
                            {service.serviceType === "Helper" && (
                                <>
                                    <p><strong>Helpers:</strong> {service.helpers}</p>
                                    <p><strong>Hours:</strong> {service.hours}</p>
                                    <p><strong>Elevator:</strong> {service.elevator}</p>
                                    <p><strong>Total Cost:</strong> {service.totalCost}</p>
                                </>
                            )}

                            {/* Cleaning Service Details */}
                            {service.serviceType === "Cleaning" && (
                                <>
                                    <p><strong>Cleaning Area:</strong> {service.cleaningArea}</p>
                                    <p><strong>Cleaners:</strong> {service.cleaners}</p>
                                    <p><strong>Square Meters:</strong> {service.squareMeters}</p>
                                    <p><strong>Cleaner Cost:</strong> {service.cleanerCost}</p>
                                    <p><strong>Total Cost:</strong> {service.totalCost}</p>
                                </>
                            )}
                        </div>
                    ))}
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={handleClose}>Close</Button>
                </Modal.Footer>
            </Modal>

        </div>
    );
};








const PendingTasks = () => {
    const [tasks, setTasks] = useState([]);


    const fetchTasks = async () => {
        const token = localStorage.getItem("tchAdminToken");
        try {
            const response = await axios.get(`${TasksApiUrl}/pending`, {
                headers: {
                    Authorization: `Bearer ${token}`, // Pass token in headers
                    "Content-Type": "application/json",
                },
            });
            if (response.data.success) {
                const formattedTasks = response.data.tasks.map(task => ({
                    id: task._id,
                    name: task.bookingId.name,
                    bookingDate: task.bookingId.bookingDate,
                    deadline: task.deadline,
                    status: task.status,
                    email: task.bookingId.email,
                    phone: task.bookingId.phone,
                    address: task.bookingId.address,
                    price: task.bookingId.price,
                    serviceData: task.bookingId.serviceData.map(service => {
                        // Handle different service types dynamically
                        if (service.serviceType === "Transport") {
                            return {
                                serviceType: service.serviceType,
                                from: service.from,
                                to: service.to,
                                distance: service.distance,
                                distanceCost: service.distanceCost,
                                total: service.total
                            };
                        } else if (service.serviceType === "Helper") {
                            return {
                                serviceType: service.serviceType,
                                totalCost: service.totalCost,
                                hours: service.hours,
                                helpers: service.helpers,
                                elevator: service.elevator
                            };
                        } else if (service.serviceType === "Cleaning") {
                            return {
                                serviceType: service.serviceType,
                                cleaningArea: service.cleaningArea,
                                cleaners: service.cleaners,
                                squareMeters: service.squareMeters,
                                cleanerCost: service.cleanerCost,
                                totalCost: service.totalCost
                            };
                        } else {
                            return { serviceType: service.serviceType };
                        }
                    })
                }));
                setTasks(formattedTasks);
            }
        } catch (error) {
            console.error("Error fetching tasks:", error);
        }
    };

    useEffect(() => {



        fetchTasks();
    }, []);

    return (
        <div className="flex flex-col items-center gap-4">
            {tasks.length > 0 ? (
                tasks.map((task) => <PendingTaskCard key={task.id} task={task} fetchTasks={fetchTasks}
                />)
            ) : (
                <p>No Tasks Found!</p>
            )}
        </div>
    );
};

export default PendingTasks;