import React, { useState, useEffect, useRef } from 'react';
import { useTranslation } from 'react-i18next';
import { motion } from 'framer-motion';
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import { Navigation, Autoplay } from 'swiper/modules';
import cleaner from "../../assets/Hero/cleaner.png"
import helper_main from "../../assets/Hero/helper_main.png"
import transport from "../../assets/Hero/transport.png"
import { Link } from 'react-router-dom';
const statistics = [
    { title: 'hero.Municipalities', value: 47, suffix: '+' },
    { title: 'hero.Our Customers', value: 157, suffix: 'K' },
    { title: 'hero.Experience', value: 5, suffix: 'år' }
];

const Counter = ({ from, to, suffix }) => {
    const [count, setCount] = useState(from);
    const ref = useRef(null);

    useEffect(() => {
        let observer = new IntersectionObserver(([entry]) => {
            if (entry.isIntersecting) {
                let start = from;
                let end = to;
                let duration = 2000;
                let stepTime = duration / (end - start);

                let timer = setInterval(() => {
                    if (start < end) {
                        start += 1;
                        setCount(start);
                    } else {
                        clearInterval(timer);
                    }
                }, stepTime);

                observer.disconnect();
            }
        }, { threshold: 0.5 });

        if (ref.current) observer.observe(ref.current);

        return () => observer.disconnect();
    }, [from, to]);

    return (
        <div ref={ref} className='flex'>
            <motion.div className='text-7xl leading-none text-right uppercase max-md:text-4xl'>
                {count}
            </motion.div>
            <span className='self-start text-4xl text-center'>{suffix}</span>
        </div>
    );
};

const TransportPage = () => {
    const { t } = useTranslation();

    const slides = [
        {
            title: t('hero.Transport solutions made simple.'),
            description: t('hero.We offer reliable transport solutions tailored to fit your needs. Whether it’s a simple move or a complex delivery, we make it easy and seamless for you.'),
            image: transport
        },
        {
            title: t('hero.Professional cleaning for you.'),
            description: t('hero.Our professional cleaning services ensure that your home or office is sparkling clean and ready for use. Experience a cleaner environment with our help.'),
            image: cleaner
        },
        {
            title: t('hero.Moving without stress or hassle.'),
            description: t('hero.Let our reliable moving helpers make your move easy and smooth. From packing to transport – we take care of everything for you.'),
            image: helper_main
        }
    ];

    return (
        <div className='max-w-[100vw] '>
            <div className='relative w-full'>
                <Swiper
                    slidesPerView={1}
                    spaceBetween={28}
                    autoplay={{ delay: 12000, disableOnInteraction: true }}
                    pagination={{ clickable: true }}
                    loop={true}
                    modules={[Navigation, Autoplay]}
                    breakpoints={{
                        0: { slidesPerView: 1, spaceBetween: 20 },
                        768: { slidesPerView: 1, spaceBetween: 28 }
                    }}
                >
                    {slides.map((slide, index) => (
                        <SwiperSlide key={index}>
                            <div
                                className="relative flex flex-col w-full pt-20"
                                style={{ backgroundImage: `url(${slide.image})`, backgroundRepeat: "no-repeat", backgroundSize: "cover", backgroundPosition: "center" }}
                            >

                                <div className='absolute inset-0 bg-gradient-to-r from-white via-white/30 to-black/70 z-[1]'></div>
                                <div className='z-20 flex relative flex-col justify-center items-start px-20 py-36 w-full max-md:px-5 max-md:py-24'>
                                    <div className=' rounded-lg max-w-[500px]'>
                                        <h1 className='text-6xl  font-bold text-sky-800 leading-[73px] max-md:text-3xl w-full'>{slide.title}</h1>
                                        <p className='mt-8 text-lg leading-7 text-zinc-800 max-md:max-w-full'>{slide.description}</p>
                                    </div>
                                    <div className='flex gap-3 items-center self-start mt-4 '>
                                        <Link to='/get-offer'>
                                            <button
                                                style={{ textWrap: "nowrap" }}
                                                className='px-9 py-3.5 text-white bg-sky-800 rounded hover:scale-105 transition-all duration-250 hover:bg-sky-900'>
                                                {t('hero.Get an offer')}
                                            </button>
                                        </Link>
                                        <Link to='/book-service'>
                                            <button
                                                style={{ textWrap: "nowrap" }}
                                                className='px-9 py-3.5 text-white bg-[#1CAC78] rounded  hover:scale-105 transition-all duration-250 hover:bg-emerald-600'>
                                                {t('hero.Book now')}
                                            </button>
                                        </Link>
                                    </div>
                                </div>
                            </div>
                        </SwiperSlide>
                    ))}

                </Swiper>
                <div className='hidden lg:flex absolute right-[77px] top-[140px] z-10 flex-col text-white w-[187px]'>
                    {statistics.map((stat, index) => (
                        <div key={index} className={`flex flex-col ${index > 0 ? 'mt-10' : ''}`}>
                            <div className='flex flex-col pl-9 w-full text-right'>
                                <div className='text-xl uppercase' style={{ textWrap: "nowrap" }}>{t(stat.title)}</div>
                                <div className='flex items-center justify-end gap-1 mt-2'>
                                    <Counter from={0} to={stat.value} suffix={stat.suffix} />
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
            {/* <div className='overflow-hidden relative gap-2.5 self-center px-2.5 py-12 -mt-6 sm:-mt-10 z-30 mx-auto w-full text-2xl font-medium leading-loose text-white bg-sky-800 max-w-[1061px] rounded-xl'>
                {t('hero.Book *****Transport*******Moving Help*****Cleaners****')}
            </div> */}
        </div>
    );
};

export default TransportPage;