import React from "react";
import { useTranslation } from "react-i18next";
import transport from "../../assets/aboutus/transport.jpg"
import moving from "../../assets/aboutus/moving.jpg"
const Section = () => {
    const { t } = useTranslation();

    return (
        <section className="md:py-24 lg:py-24 relative max-w-[100vw] overflow-x-hidden">
            <div className="w-full max-w-7xl px-4 md:px-5 lg:px-5 mx-auto">
                <div className="w-full justify-start items-center gap-12 grid lg:grid-cols-2 grid-cols-1">
                    <div
                        className="w-full justify-center items-start gap-6 grid sm:grid-cols-2 grid-cols-1">
                        <div className="pt-24 lg:justify-center sm:justify-end justify-start items-start gap-2.5 flex">
                            <img className=" rounded-xl object-cover" src={transport} alt="about Us image" />
                        </div>
                        <img className="sm:ml-0 ml-auto rounded-xl object-cover" src={moving}
                            alt="about Us image" />
                    </div>
                    <div className="w-full flex-col justify-center lg:items-start items-center gap-10 inline-flex">
                        <div className="w-full flex-col justify-center items-start gap-8 flex">
                            <div className="w-full flex-col justify-start lg:items-start items-center gap-3 flex">
                                <h1 className="text-2xl sm:text-4xl font-bold text-sky-800">
                                    <span className="text-zinc-800">{t("bottomsection.title")}</span>
                                </h1>
                                <p className="text-gray-500 text-base font-normal leading-relaxed text-start">
                                    {t("bottomsection.description")}
                                </p>
                            </div>

                            <div className="w-full lg:justify-start justify-center items-center sm:gap-10 gap-5 inline-flex">
                                <div className="flex-col justify-start items-start inline-flex">
                                    <h3 className="text-gray-900 text-xl font-bold font-manrope leading-normal">
                                        <p className="font-bold text-4xl">{t("bottomsection.years_experienceone")}</p>
                                        <p className="font-normal"> {t("bottomsection.years_experience")}</p>
                                    </h3>
                                </div>
                                <div className="flex-col justify-start items-start inline-flex">
                                    <h3 className="text-gray-900 text-xl font-bold font-manrope leading-normal">
                                        <p className="font-bold text-4xl">{t("bottomsection.customers_servedone")}</p>
                                        <p className="font-normal"> {t("bottomsection.customers_served")}</p>
                                    </h3>
                                </div>
                                <div className="flex-col justify-start items-start inline-flex">
                                    <h3 className="text-gray-900 text-xl font-bold font-manrope leading-normal">
                                        <p className="font-bold text-4xl">{t("bottomsection.service_locationsone")}</p>
                                        <p className="font-normal"> {t("bottomsection.service_locations")}</p>
                                    </h3>
                                </div>
                            </div>
                        </div>

                        <div className="flex gap-3 items-center self-start mt-8 text-base font-medium text-center">
                            <button className="gap-2.5 self-stretch hover:scale-105 transition-all duration-250 px-9 py-3.5 my-auto sm:w-48 text-white rounded border border-[#1CAC78] bg-[#1CAC78] border-solid min-h-[46px] max-md:px-5">
                                {t("bottomsection.book_now")}
                            </button>
                        </div>
                    </div>


                </div>
            </div>
        </section>
    );
};

export default Section;
