import React from "react";
import { useTranslation } from "react-i18next";
import { Link } from "react-router-dom";
import about from "../../assets/aboutsection/about.png"
const AboutSection = () => {
    const { t } = useTranslation();

    return (
        <div className="grid grid-cols-1 lg:grid-cols-2 place-content-center place-items-center gap-10 px-20 py-5 max-md:px-5">
            <div className="flex flex-col justify-center self-stretch sm:py-16">
                <img src={about} alt="About Us" />
            </div>
            <div className="flex flex-col justify-between items-center self-stretch my-auto">
                <div className="flex flex-col w-full">
                    <div className="flex flex-col justify-between w-full">
                        <div className="flex flex-col w-full font-bold uppercase max-md:max-w-full">
                            <div data-aos="fade-right" className="flex flex-wrap gap-6 items-center w-full text-xl sm:text-2xl leading-none text-sky-800 tracking-[5.52px] max-md:max-w-full">
                                <div className="h-[2px] rounded-md my-auto bg-[#1CAC78] w-[70px] sm:w-[115px]" />
                                <div className="self-stretch text-[#1CAC78] my-auto">{t("about.title")}</div>
                            </div>
                            <div data-aos="fade-down" className="mt-4 text-2xl md:text-4xl leading-10 text-gray-900 max-md:max-w-full">
                                {t("about.subtitle")}
                            </div>
                        </div>
                        <div className="flex flex-col justify-between mt-7 w-full max-md:max-w-full">
                            <div className="text-base leading-7 text-zinc-800 max-md:max-w-full">
                                {t("about.description")}
                            </div>
                            <Link to="/book-now">
                                <button className="gap-2.5 mt-5 self-stretch hover:scale-105 transition-all duration-250 px-9 py-3.5 my-auto sm:w-48 text-white rounded border border-[#1CAC78] bg-[#1CAC78] border-solid min-h-[46px] max-md:px-5">
                                    {t("about.bookNow")}
                                </button>
                            </Link>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AboutSection;