import { useState } from "react";
import axios from "../../Https/Axios";
import { OffersApiUrl } from "../../Https/UserSideAxiosUrls";
import bg_image from "../../assets/getofferform/cargo.png"
import { useTranslation } from "react-i18next";

const GetOffer = () => {

  const { t } = useTranslation();


  const [formData, setFormData] = useState({
    whoAmI: "",
    name: "",
    email: "",
    phone: "",
    date: "",
    time: "",
    services: [],
    specialRequirements: "",
    agree: false,
    transportDetails: {},
    cleaningDetails: {},
    helperDetails: {}
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");
  const [selectAll, setSelectAll] = useState(false);


  const handleSelectAll = (e) => {
    const isChecked = e.target.checked;
    setSelectAll(isChecked);

    const allServices = [
      t("getofferform.transport"),
      t("getofferform.cleaning"),
      t("getofferform.helper"),
    ];

    setFormData((prev) => ({
      ...prev,
      services: isChecked ? allServices : [],
    }));
  };


  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
  
    if (type === "checkbox" && name === "services") {
      setFormData((prev) => {
        const newServices = checked
          ? [...prev.services, value]
          : prev.services.filter((service) => service !== value);
  
        // Update selectAll if all services are selected
        setSelectAll(newServices.length === 3);
  
        return {
          ...prev,
          services: newServices,
        };
      });
    } else if (type === "checkbox") {
      setFormData((prev) => ({ ...prev, [name]: checked }));
    } else {
      setFormData((prev) => ({ ...prev, [name]: value }));
    }
  };
  

  const handleServiceChange = (e, service) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [`${service}Details`]: { ...prev[`${service}Details`], [name]: value },
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage("");

    try {
      const response = await axios.post(OffersApiUrl, formData);
      setMessage("Service request submitted successfully!");
      setFormData({
        whoAmI: "",
        name: "",
        email: "",
        phone: "",
        date: "",
        time: "",
        services: [],
        specialRequirements: "",
        agree: false,
        transportDetails: {},
        cleaningDetails: {},
        helperDetails: {}
      });
    } catch (error) {
      console.error("Error submitting request:", error);
      setMessage("Failed to submit the request. Please try again.");
    }

    setLoading(false);
  };

  return (
    <div className="relative z-0 px-4 py-24 md:px-4 md:py-24 lg:px-40 lg:py-28">
      <div className="absolute inset-0 bg-black opacity-50 z-0"></div>

      <img
        src={bg_image}
        alt="banner"
        className="object-cover -z-10 absolute inset-0 size-full"
      />

      <h1 className="relative w-full text-center font-bold text-3xl mt-16 mb-4 text-white z-10">
        {t("getofferform.title")}
      </h1>
      <div className="flex">
        <div className="p-10"></div>
        <div className="p-10"></div>
        <div className="relative z-10 bg-white w-full shadow-md p-6 rounded-lg">
          {message && <p className="text-center text-green-500">{message}</p>}
          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium"> {t("getofferform.whoAmI")}</label>
                <select
                  name="whoAmI"
                  value={formData.whoAmI}
                  onChange={handleChange}
                  className="w-full border rounded-lg p-2"
                >
                  <option value="">{t("getofferform.selectWho")} </option>
                  <option value="Student">{t("getofferform.student")}</option>
                  <option value="Private Individual">{t("getofferform.privateIndividual")}</option>
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium">{t("getofferform.enterName")}</label>
                <input
                  type="text"
                  name="name"
                  value={formData.name}
                  onChange={handleChange}
                  className="w-full border rounded-lg p-2"
                  placeholder="Your name"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium">{t("getofferform.enterEmail")}</label>
                <input
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  className="w-full border rounded-lg p-2"
                  placeholder="Enter email"
                />
              </div>
              <div>
                <label className="block text-sm font-medium">
                  {t("getofferform.enterPhone")}
                </label>
                <input
                  type="text"
                  name="phone"
                  value={formData.phone}
                  onChange={handleChange}
                  className="w-full border rounded-lg p-2"
                  placeholder="Enter phone number"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium">{t("getofferform.bestDate")}</label>
                <input
                  type="date"
                  name="date"
                  value={formData.date}
                  onChange={handleChange}
                  className="w-full border rounded-lg p-2"
                />
              </div>
              <div>
                <label className="block text-sm font-medium">{t("getofferform.bestTime")}</label>
                <input
                  type="time"
                  name="time"
                  value={formData.time}
                  onChange={handleChange}
                  className="w-full border rounded-lg p-2"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium">{t("getofferform.selectServices")}</label>
              <div className="flex flex-col gap-2">
                <label className="flex items-center gap-2">
                  <input
                    type="checkbox"
                    checked={selectAll}
                    onChange={handleSelectAll}
                  />
                  {t("getofferform.selectAll")}
                </label>

                {[t("getofferform.transport"), t("getofferform.cleaning"), t("getofferform.helper")].map((service) => (
                  <label key={service} className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      name="services"
                      value={service}
                      checked={formData.services.includes(service)}
                      onChange={handleChange}
                    />
                    {service}
                  </label>
                ))}
              </div>
            </div>


            {formData.services.includes(t("getofferform.transport")) && (
              <div>
                <label className="block text-sm font-medium">{t("getofferform.transportDetails")}</label>
                <select name="frequency" onChange={(e) => handleServiceChange(e, "transport")} className="w-full border rounded-lg p-2">
                  <option value="">Select Frequency</option>
                  <option value="one-time">{t("getofferform.oneTime")}</option>
                  <option value="weekly">{t("getofferform.weekly")}</option>
                  <option value="monthly">{t("getofferform.monthly")}</option>
                </select>
                <input type="text" name="from" placeholder={t('getofferform.from')} onChange={(e) => handleServiceChange(e, "transport")} className="w-full border rounded-lg p-2 mt-2" />
                <input type="text" name="to" placeholder={t('getofferform.to')} onChange={(e) => handleServiceChange(e, "transport")} className="w-full border rounded-lg p-2 mt-2" />
                <input type="number" name="distance" placeholder={t('getofferform.distance')} onChange={(e) => handleServiceChange(e, "transport")} className="w-full border rounded-lg p-2 mt-2" />
              </div>
            )}

            {formData.services.includes(t("getofferform.cleaning")) && (
              <div>
                <label className="block text-sm font-medium">{t("getofferform.cleaningDetails")}</label>
                <select name="frequency" onChange={(e) => handleServiceChange(e, "cleaning")} className="w-full border rounded-lg p-2">
                  <option value="">Select Frequency</option>
                  <option value="one-time">{t("getofferform.oneTime")}</option>
                  <option value="weekly">{t("getofferform.weekly")}</option>
                  <option value="monthly">{t("getofferform.monthly")}</option>
                </select>
                <input type="number" name="area" placeholder={t('getofferform.area')} onChange={(e) => handleServiceChange(e, "cleaning")} className="w-full border rounded-lg p-2 mt-2" />
                <input type="number" name="cleaners" placeholder={t('getofferform.cleaners')} onChange={(e) => handleServiceChange(e, "cleaning")} className="w-full border rounded-lg p-2 mt-2" />
              </div>
            )}

            {formData.services.includes(t("getofferform.helper")) && (
              <div>
                <label className="block text-sm font-medium">{t("getofferform.helperDetails")}</label>
                <select name="frequency" onChange={(e) => handleServiceChange(e, "helper")} className="w-full border rounded-lg p-2">
                  <option value="">{t("getofferform.selectFrequency")}</option>
                  <option value="one-time">{t("getofferform.oneTime")}</option>
                  <option value="weekly">{t("getofferform.weekly")}</option>
                  <option value="monthly">{t("getofferform.monthly")}</option>
                </select>
                <input type="number" name="hours" placeholder={t('getofferform.hours')} onChange={(e) => handleServiceChange(e, "helper")} className="w-full border rounded-lg p-2 mt-2" />
                <input type="number" name="helpers" placeholder={t('getofferform.helpers')} onChange={(e) => handleServiceChange(e, "helper")} className="w-full border rounded-lg p-2 mt-2" />
                <select name="elevator" onChange={(e) => handleServiceChange(e, "helper")} className="w-full border rounded-lg p-2 mt-2">
                  <option value="">{t('getofferform.elevator')}</option>
                  <option value="yes">{t('getofferform.yes')}</option>
                  <option value="no">{t('getofferform.no')}</option>
                </select>
                {formData.helperDetails?.elevator === "no" && (
                  <input type="number" name="floors" placeholder={t('getofferform.floors')} onChange={(e) => handleServiceChange(e, "helper")} className="w-full border rounded-lg p-2 mt-2" />
                )}

              </div>
            )}

















            <div>
              <label className="block text-sm font-medium">{t('getofferform.specialRequirements')}</label>
              <textarea
                name="specialRequirements"
                value={formData.specialRequirements}
                onChange={handleChange}
                className="w-full border rounded-lg p-2 h-24"
                placeholder="Enter any special requirements..."
              ></textarea>
            </div>

            <div>
              <label className="flex items-center gap-2">
                <input
                  type="checkbox"
                  name="agree"
                  checked={formData.agree}
                  onChange={handleChange}
                />
                {t('getofferform.agreeTerms')}
              </label>
            </div>
            <div className="flex justify-end">
              <button
                type="submit"
                className="btn btn-lg text-white px-20 mt-3"
                disabled={loading}
                style={{ backgroundColor: "#035E89" }}
              >
                {loading ? "Submitting..." : t('getofferform.submit')}

              </button>
            </div>
          </form>
        </div>
        <div className="p-10"></div>
        <div className="p-10"></div>

      </div>
    </div>
  );
};

export default GetOffer;
