import React, { useEffect, useState } from "react";
import axios from "../../Https/Axios";
import { EmployeeApiUrl } from "../../Https/AdminSideAxiosUrls"
import { Button, Modal, Form } from "react-bootstrap";
import { FaEdit, FaTrashAlt } from "react-icons/fa";

import Swal from "sweetalert2";

// Function to get token from local storage
const getToken = () => localStorage.getItem("tchAdminToken");

// Define possible work types
const WORK_TYPES = ["Cleaner", "Transporter", "Moving Assistance"];

const Employees = () => {
  const [showModal, setShowModal] = useState(false);
  const [currentEmployee, setCurrentEmployee] = useState(null);
  const [searchTerm, setSearchTerm] = useState("");

  const [employees, setEmployees] = useState([]);

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = async () => {
    try {
      const response = await axios.get(EmployeeApiUrl, {
        headers: { Authorization: `Bearer ${getToken()}` },
      });
      setEmployees(response.data);
    } catch (error) {
      console.error("Error fetching employees:", error);
    }
  };

  const handleEdit = (employee) => {
    setCurrentEmployee(employee);
    setShowModal(true);
  };

  const handleSave = async () => {
    try {
      await axios.put(`${EmployeeApiUrl}/${currentEmployee._id}`, currentEmployee, {
        headers: { Authorization: `Bearer ${getToken()}` },
      });
      fetchEmployees();
      setShowModal(false);
    } catch (error) {
      console.error("Error updating employee:", error);
    }
  };


  const handleDelete = async (id) => {
    Swal.fire({
      title: "Are you sure?",
      text: "Are you sure you want to delete? If Yes, then it will be deleted permanently!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#d33",
      cancelButtonColor: "#3085d6",
      confirmButtonText: "Yes, delete it!",
    }).then(async (result) => {
      if (result.isConfirmed) {
        try {
          await axios.delete(`${EmployeeApiUrl}/${id}`, {
            headers: { Authorization: `Bearer ${getToken()}` },
          });

          setEmployees(employees.filter((emp) => emp._id !== id));

          Swal.fire("Deleted!", "Employee has been deleted.", "success");
        } catch (error) {
          console.error("Error deleting employee:", error);
          Swal.fire("Error!", "Failed to delete employee.", "error");
        }
      }
    });
  };


  const toggleWorkType = (workType) => {
    if (!currentEmployee) return;
    const updatedTypes = currentEmployee.typeofwork.includes(workType)
      ? currentEmployee.typeofwork.filter((type) => type !== workType)
      : [...currentEmployee.typeofwork, workType];

    setCurrentEmployee({ ...currentEmployee, typeofwork: updatedTypes });
  };

  return (
    <div className="py-2 container">
      <div className="mb-4 flex items-center  w-full">
        <div className="flex w-full items-center justify-between">
          <h1 className="text-2xl font-bold">Employees List</h1>
          <div>

            <input
              type="text"
              placeholder="Search employees..."
              className="p-3 w-full form-control"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>
      </div>


      <div>
        {employees.filter((employee) =>
          employee.name.toLowerCase().includes(searchTerm.toLowerCase())
        ).length === 0 ? (
          <p className="text-center text-gray-500 text-lg">No employees found.</p>
        ) : (
          <div className="grid md:grid-cols-3 lg:grid-cols-4 gap-6">
            {employees
              .filter((employee) => employee.name.toLowerCase().includes(searchTerm.toLowerCase()))
              .map((employee) => (
                <div key={employee._id} className="p-3 rounded-lg shadow-xl flex flex-col">
                  <div className="flex justify-start gap-3 items-center">
                    <div className="text-start">
                      <h2 className="text-xl font-semibold">{employee.name}</h2>
                      <p className="text-gray-600 mb-2"> {employee.typeofwork.join(", ")}</p>
                      <p className="text-gray-600"><strong>Email:</strong> {employee.email}</p>
                      <p className="text-gray-600"><strong>Phone:</strong> {employee.phone}</p>
                      <p className="text-gray-600"><strong>Address:</strong> {employee.address}</p>
                      <p className="text-gray-600"><strong>Driving License:</strong> {employee.haveDrivingLicense}</p>
                      <p className="text-gray-600"><strong>License No:</strong> {employee.licenceNumber || "N/A"}</p>
                    </div>
                  </div>
                  <div className="mt-3 flex justify-center gap-3">
                    <button className="text-white bg-yellow-400 rounded-pill p-2 px-4" onClick={() => handleEdit(employee)}>
                      <FaEdit size={20} />
                    </button>
                    <button className="text-white bg-danger rounded-pill p-2 px-4" onClick={() => handleDelete(employee._id)}>
                      <FaTrashAlt size={20} />
                    </button>
                  </div>
                </div>
              ))}
          </div>
        )}
      </div>


      {currentEmployee && (
        <Modal show={showModal} onHide={() => setShowModal(false)} centered size="lg">
          <Modal.Header closeButton>
            <Modal.Title>Edit Employee</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Form>
              <Form.Group>
                <Form.Label>Name</Form.Label>
                <Form.Control
                  type="text"
                  value={currentEmployee.name}
                  onChange={(e) => setCurrentEmployee({ ...currentEmployee, name: e.target.value })}
                />
              </Form.Group>
              <Form.Group>
                <Form.Label>Email</Form.Label>
                <Form.Control
                  type="email"
                  value={currentEmployee.email}
                  onChange={(e) => setCurrentEmployee({ ...currentEmployee, email: e.target.value })}
                />
              </Form.Group>
              <Form.Group>
                <Form.Label>Phone</Form.Label>
                <Form.Control
                  type="text"
                  value={currentEmployee.phone}
                  onChange={(e) => setCurrentEmployee({ ...currentEmployee, phone: e.target.value })}
                />
              </Form.Group>
              <Form.Group>
                <Form.Label>Address</Form.Label>
                <Form.Control
                  type="text"
                  value={currentEmployee.address}
                  onChange={(e) => setCurrentEmployee({ ...currentEmployee, address: e.target.value })}
                />
              </Form.Group>
              <Form.Group>
                <Form.Label>Driving License</Form.Label>
                <Form.Control
                  as="select"
                  value={currentEmployee.haveDrivingLicense}
                  onChange={(e) => setCurrentEmployee({ ...currentEmployee, haveDrivingLicense: e.target.value })}
                >
                  <option value="Yes">Yes</option>
                  <option value="No">No</option>
                </Form.Control>
              </Form.Group>
              <Form.Group>
                <Form.Label>License Number</Form.Label>
                <Form.Control
                  type="text"
                  value={currentEmployee.licenceNumber}
                  onChange={(e) => setCurrentEmployee({ ...currentEmployee, licenceNumber: e.target.value })}
                />
              </Form.Group>

              {/* Work Type Checkboxes */}
              <Form.Group>
                <Form.Label>Work Type</Form.Label>
                {WORK_TYPES.map((work) => (
                  <Form.Check
                    key={work}
                    type="checkbox"
                    label={work}
                    checked={currentEmployee.typeofwork.includes(work)}
                    onChange={() => toggleWorkType(work)}
                  />
                ))}
              </Form.Group>

              <div className="flex justify-end mt-4">
                <Button variant="success" className="px-4 py-2" onClick={handleSave}>
                  Save Changes
                </Button>
              </div>
            </Form>
          </Modal.Body>
        </Modal>
      )}
    </div>
  );
};

export default Employees;