import React from "react";
import { BrowserRouter, Routes, Route, Navigate, useLocation } from "react-router-dom";
import Home from "./pages/Home/Home.js";
// import Footer from "./components/Footer.js";
import Footer from "./components/Footer/Footer.js";
import Navbar from "./components/Navbar/Navbar.js";
import NavigationBar from "./components/Header/Header.js";
import AboutUsMain from "./pages/AboutUs/AboutUs.js";
import BeOurPartner from "./pages/BeAPartner/BeAPartner.js";
import Work from "./pages/WorkWithUs/Work.js";
import GetOfferMain from "./pages/GetOffer/GetOffer.js";
import LoginSignUp from "./Dashbaord/LoginSignUp/LoginSignUp.js"
import Dashboard from "./Dashbaord/Dashboard/Dashboard.js"
import GetOfferForm from "./pages/Offer/OfferForm.js";
import "./App.css";
import StripePayment from "./pages/Stripe.jsx";
import KlarnaPayForm from "./pages/KlarnaPayForm.js";
const AppRouter = () => {
    const location = useLocation();
    const isAdminRoute = location.pathname.startsWith("/admin") || location.pathname.startsWith("/userDashboard") || location.pathname.startsWith("/dashboard");
    const admintoken = localStorage.getItem("tchAdminToken");
    return (
        <>
            {!isAdminRoute && <NavigationBar />}
            <Routes>
                <Route path="/" exact element={<Home />} />
                <Route path="/partner" exact element={<BeOurPartner />} />
                <Route path="/about-us" exact element={<AboutUsMain />} />
                <Route path="/work" exact element={<Work />} />
                <Route path="/book-service" exact element={<GetOfferMain />} />
                <Route path="/get-offer" exact element={<GetOfferForm />} />
                <Route path="/stripe-payment" exact element={<StripePayment />} />
                <Route path="/klarna-payment" exact element={<KlarnaPayForm />} />


                <Route path="/admin/login" exact element={<LoginSignUp />} />

                <Route
                    path="/admin/dashboard"
                    exact
                    element={admintoken ? <Dashboard /> : <Navigate to="/admin/login" />}
                />
            </Routes>
            {!isAdminRoute && <Footer />}

        </>
    );
};

export default AppRouter;
