import React, { useState } from "react";
import { Form, Button, Spinner } from "react-bootstrap";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import { useTranslation } from "react-i18next";
import axios from "../../Https/Axios";
import { PartnersApiUrl } from "../../Https/UserSideAxiosUrls"
const PartnerForm = ({ setIsModalOpen }) => {
    const { t } = useTranslation();
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        email: "",
        phone: "",
        vehicleNumber: "",
        licenseNumber: "",
        vans: 0,
        transportPermit: false,
        liabilityInsurance: false,
    });

    const [isTerm, setIsTerm] = useState(false);

    const handleChange = (key, value) => {
        setFormData((prevData) => ({
            ...prevData,
            [key]: value,
        }));
    };

   

    const handleSubmit = async () => {
        if (!isTerm) {
            toast.error(t("toast.errorTerms"));
            return;
        }
        if (
            !formData.name ||
            !formData.email ||
            !formData.phone ||
            !formData.vehicleNumber ||
            !formData.licenseNumber 
        ) {
            return toast.error(t("toast.errorRequired"));
        }

        setLoading(true);
        try {
            const formDataToSend = new FormData();
            formDataToSend.append("name", formData.name);
            formDataToSend.append("email", formData.email);
            formDataToSend.append("phone", formData.phone);
            formDataToSend.append("vehicleNumber", formData.vehicleNumber);
            formDataToSend.append("licenseNumber", formData.licenseNumber);
            formDataToSend.append("vans", formData.vans);
            formDataToSend.append("transportPermit", formData.transportPermit);
            formDataToSend.append("liabilityInsurance", formData.liabilityInsurance);

            const response = await axios.post(PartnersApiUrl, formDataToSend, {
                headers: {
                    "Content-Type": "application/json",
                  },
            });
            alert("Your Request has been sent , we will reach you shortly");
            setIsModalOpen(true);
            setFormData({
                name: "",
                email: "",
                phone: "",
                vehicleNumber: "",
                licenseNumber: "",
                vans: 0,
                transportPermit: false,
                liabilityInsurance: false,
            });
        } catch (error) {
            const errorMessage = error.response?.data?.message || t("toast.error");
            toast.error(errorMessage);
        } finally {
            setLoading(false);
        }
    };


    return (
        <div className="bg-white shadow-lg flex items-center justify-center rounded-3xl flex-col w-11/12 md:w-8/12 p-4 2xl:w-7/12">
           
            <div className="flex flex-col md:flex-row w-full gap-3">
                <div className="w-full mb-4">
                    <Form.Group>
                        <Form.Label className="text-black font-semibold">{t("partnerform.form.name")}</Form.Label>
                        <Form.Control
                            className="py-2"
                            type="text"
                            value={formData.name}
                            onChange={(e) => handleChange("name", e.target.value)}
                        />
                    </Form.Group>
                </div>
                <div className="w-full mb-4">
                    <Form.Group>
                        <Form.Label className="text-black font-semibold">{t("partnerform.form.email")}</Form.Label>
                        <Form.Control
                            className="py-2"
                            type="email"
                            value={formData.email}
                            onChange={(e) => handleChange("email", e.target.value)}
                        />
                    </Form.Group>
                </div>
            </div>

            <div className="w-full mb-4">
                <Form.Group>
                    <Form.Label className="text-black font-semibold">{t("partnerform.form.phone")}</Form.Label>
                    <Form.Control
                        className="py-2"
                        type="tel"
                        value={formData.phone}
                        onChange={(e) => handleChange("phone", e.target.value)}
                    />
                </Form.Group>
            </div>

            <div className="flex flex-col md:flex-row w-full gap-3">
                <div className="w-full mb-4">
                    <Form.Group>
                        <Form.Label className="text-black font-semibold">{t("partnerform.form.vehicleNumber")}</Form.Label>
                        <Form.Control
                            className="py-2"
                            type="text"
                            value={formData.vehicleNumber}
                            onChange={(e) => handleChange("vehicleNumber", e.target.value)}
                        />
                    </Form.Group>
                </div>

                <div className="w-full mb-4">
                    <Form.Group>
                        <Form.Label className="text-black font-semibold">{t("partnerform.form.licenseNumber")}</Form.Label>
                        <Form.Control
                            className="py-2"
                            type="text"
                            value={formData.licenseNumber}
                            onChange={(e) => handleChange("licenseNumber", e.target.value)}
                        />
                    </Form.Group>
                </div>
            </div>

            <div className="w-full mb-4">
                <Form.Group>
                    <Form.Label className="text-black font-semibold">{t("partnerform.form.vans")}</Form.Label>
                    <Form.Control
                        className="py-2"
                        type="number"
                        min="0"
                        value={formData.vans}
                        onChange={(e) => handleChange("vans", parseInt(e.target.value, 10) || 0)}
                    />
                </Form.Group>
            </div>

            <div className="w-full mt-2">
                <Form.Check
                    type="checkbox"
                    label={t("partnerform.form.transportPermit")}
                    checked={formData.transportPermit}
                    onChange={(e) => handleChange("transportPermit", e.target.checked)}
                />
            </div>

            <div className="w-full mt-2">
                <Form.Check
                    type="checkbox"
                    label={t("partnerform.form.liabilityInsurance")}
                    checked={formData.liabilityInsurance}
                    onChange={(e) => handleChange("liabilityInsurance", e.target.checked)}
                />
            </div>

            <div className="w-full mt-4">
                <Form.Check
                    type="checkbox"
                    label={t("partnerform.form.agreeTerms")}
                    checked={isTerm}
                    onChange={() => setIsTerm(!isTerm)}
                />
            </div>

            <div className="flex gap-3 w-full justify-end self-start mt-8">
                <Button
                    onClick={handleSubmit}
                    className="px-4 py-3 w-56 text-white border border-[#1CAC78] !bg-[#1CAC78]"
                    disabled={loading}
                >
                    {loading ? <Spinner animation="border" size="sm" /> : t("partnerform.form.submit")}
                </Button>
            </div>
        </div>
    );
};

export default PartnerForm;
