import React from "react";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import transport from "../../assets/servicessection/transport.jpg"
import helper from "../../assets/servicessection/helper.jpg"
import cleaning from "../../assets/servicessection/cleaning.jpg"
const ServiceCard = ({ title, description,description2, image , btn }) => {
    return (
        <div className="relative flex flex-col w-full sm:w-[350px] h-full rounded-2xl overflow-hidden">
            {/* Background Image */}
            <div
                className="absolute inset-0 bg-cover bg-center"
                style={{ backgroundImage: `url(${image})` }}
            ></div>

            {/* Transparent Overlay */}
            <div className="absolute inset-0 bg-black bg-opacity-50 rounded-2xl"></div>

            {/* Content */}
            <div className="relative py-10 flex-col items-center p-6 ">
                <h2 className="text-xl lg:text-2xl mb-2 mt-3 font-bold text-white">{title}</h2>
                <p className="mb-2 mt-3 text-base text-white">{description}</p>
                <p className="mb-2 mt-3 text-base text-white">{description2}</p>
                <Link to="/book-service">
                    <button className="mb-2 mt-3 bg-emerald-500 text-white px-6 py-2 rounded-lg hover:scale-105 transition duration-300">
                        {btn}
                    </button>
                </Link>
            </div>
        </div>
    );
};





const AllCards = () => {
    const { t } = useTranslation();
    const homeServices = t("homeservices", { returnObjects: true });
    const servicesData = homeServices.homeservices || [];
    const buttonText = homeServices.button || "Select"; 
    const serviceImages = [transport, helper, cleaning];

    return (
        <div className="flex justify-center items-start py-10 w-full">
            <div className="flex flex-wrap flex-col sm:flex-row px-4 md:px-20 justify-center gap-6 w-full">
                {servicesData.map((service, index) => (
                    <div className="w-full sm:w-auto" key={index}>
                        <ServiceCard
                            title={service.title}
                            image={serviceImages[index % serviceImages.length]}
                            description={service.description}
                            description2={service.description2}
                            btn={buttonText}
                        />
                    </div>
                ))}
            </div>
        </div>
    );
};


export default AllCards;
