import React, { useState } from "react";
import { loadStripe } from "@stripe/stripe-js";
import { Elements, useStripe, useElements, CardElement } from "@stripe/react-stripe-js";
import axios from "../Https/Axios";
import { paymentApiUrl } from "../Https/UserSideAxiosUrls";
import { useLocation } from "react-router-dom";

// const stripePromise = loadStripe("pk_live_51QSlqUBQQlC38lZKeTkvItVlkdFrhh50QkE4g9NWHwamMnRakwc3f8VNQwDKuREmA25hMZi9F7i8c9FZwFlPp3aI00Cst3PFFB");
const stripePromise = loadStripe("pk_test_51QSlqUBQQlC38lZKnPMgeQxzLkuq6TdhvdXS4MlCQ3dvuqUGzD98yGxjoVv2h7tiHPCssz4ORmbYu3wfeHDfQvIP00efUDnl3Q");

const CheckoutForm = () => {


    const location = useLocation();
    const totalCost = location.state?.totalCost;

    const stripe = useStripe();
    const elements = useElements();
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState("");
    const [amount, setAmount] = useState(totalCost);

    const handleSubmit = async (event) => {
        event.preventDefault();
        setLoading(true);

        const parsedAmount = parseFloat(amount);
        if (isNaN(parsedAmount) || parsedAmount <= 0) {
            setMessage("Please enter a valid amount.");
            setLoading(false);
            return;
        }

        const { data } = await axios.post(paymentApiUrl, {
            amount: parsedAmount,
            currency: "sek",
        });

        const { clientSecret } = data;

        if (!stripe || !elements) {
            console.error("Stripe or Elements not loaded");
            setLoading(false);
            return;
        }

        const result = await stripe.confirmCardPayment(clientSecret, {
            payment_method: { card: elements.getElement(CardElement) },
        });

        if (result.error) {
            console.error("Payment Error:", result.error);
            setMessage(result.error.message);
        } else {
            setMessage("Payment successful!");
        }

        setLoading(false);
    };


    return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100">
            <div className="bg-white p-6 rounded-lg shadow-md w-full max-w-md">
                <h2 className="text-2xl font-bold mb-4">Payment Here...</h2>

                <form onSubmit={handleSubmit} className="space-y-4">
                    <input
                        type="number"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        className="w-full p-2 border border-gray-300 rounded-md"
                        readOnly
                    />
                    <div className="border border-gray-300 p-3 rounded-md">
                        <CardElement className="p-2" />
                    </div>
                    <button
                        type="submit"
                        className="w-full bg-yellow-400 text-white py-2 rounded-md hover:bg-yellow-400 transition disabled:bg-gray-400"
                        disabled={!stripe || loading}
                    >
                        {loading ? "Processing..." : `Pay kr${amount}`} 
                    </button>

                    {message && <p className="text-center text-red-500">{message}</p>}
                </form>
            </div>
        </div>
    );
};

const StripePayment = () => (
    <Elements stripe={stripePromise}>
        <CheckoutForm />
    </Elements>
);

export default StripePayment;