import React, { useEffect, useState } from "react";
import axios from "../../Https/Axios";
import { OffersApiUrl, BookingsApiUrl } from "../../Https/AdminSideAxiosUrls";
import { FaEnvelope, FaPhone, FaCalendarAlt, FaClock, FaListUl, FaTruck, FaBroom, FaUserFriends } from "react-icons/fa";

const Offers = () => {
    const [offers, setOffers] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [loadingBookingId, setLoadingBookingId] = useState(null);

    useEffect(() => {
        const fetchOffers = async () => {
            try {
                const response = await axios.get(OffersApiUrl);
                if (response.data && response.data.data) {
                    setOffers(response.data.data);
                }
            } catch (err) {
                setError("Failed to fetch offers.");
            } finally {
                setLoading(false);
            }
        };
        fetchOffers();
    }, []);



    const handleAddToBooking = async (offer) => {

        setLoadingBookingId(offer._id); // disable button for this offer


        const bookingData = {
            name: offer.name,
            bookingDate: offer.date,
            scheduledTime: offer.time,
            status: "pending",
            email: offer.email,
            phone: offer.phone,
            address: offer.address || "N/A", // fallback if address is missing
            price: offer.totalPrice || "SEK 0",
            serviceData: []
        };

        // Add Cleaning details
        if (offer.cleaningDetails) {
            const { area, cleaners } = offer.cleaningDetails;
            const squareCost = `${area} * SEK 1/sq. ft. = SEK ${parseInt(area)}`
            const cleanerCost = `${cleaners} cleaners * SEK 70 = SEK ${cleaners * 70}`
            const totalCost = `SEK ${parseInt(area) + (cleaners * 70)}`
            bookingData.serviceData.push({
                serviceType: "Cleaning",
                cleaningArea: area + " sq ft",
                cleaners,
                squareMeters: squareCost,
                cleanerCost,
                totalCost
            });
        }

        // Add Transport details
        if (offer.transportDetails) {
            const { from, to, distance } = offer.transportDetails;
            const distanceCost = `${distance} km * SEK 18/km = SEK ${distance * 18}`;
            const total = `SEK ${distance * 18}`;
            bookingData.serviceData.push({
                serviceType: "Transport",
                from,
                to,
                distance: `${distance} km`,
                distanceCost,
                total
            });
        }

        // Add Helper details
        if (offer.helperDetails) {
            const { hours, helpers, elevator, floors } = offer.helperDetails;
            const totalCost = `${hours} hours * ${helpers} helpers * SEK 399 = SEK ${hours * helpers * 399}`;
            const floorCost = `${floors} floors * SEK 100 = SEK ${floors * 100}`;
            const total = `SEK ${hours * helpers * 399 + floors * 100}`;
            bookingData.serviceData.push({
                serviceType: "Helper",
                hours,
                helpers,
                elevator,
                totalCost,
                floorCost,
                total
            });
        }

        try {
            const response = await axios.post(BookingsApiUrl, bookingData);
            alert("Booking added successfully!");
            console.log("Booking response:", response.data);
        } catch (error) {
            alert("Failed to add booking.");
            console.error("Booking error:", error);
        }

        finally {
            setLoadingBookingId(null);
        }
    };




    if (loading) return <p className="text-center text-lg font-semibold animate-pulse">Loading offers...</p>;
    if (error) return <p className="text-center text-red-500 font-semibold">{error}</p>;

    return (
        <div className="p-8 min-h-screen flex flex-col items-center">
            <h2 className="text-4xl font-extrabold text-gray-900 mb-10 tracking-wide w-full text-start">My Offers</h2>
            <div className="grid grid-cols-1  gap-8 w-full max-w-7xl">
                {offers.map((offer) => (
                    <div key={offer._id} className="bg-white shadow-lg rounded-xl p-6 border border-gray-200 hover:shadow-xl transition-all duration-300">
                        {/* 🔹 First Row (Basic Info) */}
                        <div className="flex flex-wrap justify-between items-center border-b pb-3 mb-3">
                            <h3 className="text-xl font-bold text-gray-800">{offer.name}</h3>
                            <div className="flex flex-wrap gap-3 text-gray-600">
                                <span className="flex items-center gap-1"><FaEnvelope className="text-blue-500" /> {offer.email}</span>
                                <span className="flex items-center gap-1"><FaPhone className="text-green-500" /> {offer.phone}</span>
                                <span className="flex items-center gap-1"><FaCalendarAlt className="text-red-500" /> {offer.date}</span>
                                <span className="flex items-center gap-1"><FaClock className="text-yellow-500" /> {offer.time}</span>
                                <span className="flex items-center gap-1"><FaListUl className="text-purple-500" /> {offer.services?.join(", ")}</span>
                            </div>
                        </div>

                        {/* 🔹 Second Row (Detailed Info) */}
                        <div className="space-y-3">
                            {/* Transport Details */}
                            {offer.transportDetails && (
                                <div className="p-3 border rounded-lg bg-gray-100">
                                    <h4 className="text-lg font-semibold flex items-center gap-2"><FaTruck className="text-blue-600" /> Transport</h4>
                                    <p className="text-gray-700">🛣️ {offer.transportDetails.frequency}, From {offer.transportDetails.from} to {offer.transportDetails.to}, {offer.transportDetails.distance} km</p>
                                </div>
                            )}

                            {/* Cleaning Details */}
                            {offer.cleaningDetails && (
                                <div className="p-3 border rounded-lg bg-gray-100">
                                    <h4 className="text-lg font-semibold flex items-center gap-2"><FaBroom className="text-green-600" /> Cleaning</h4>
                                    <p className="text-gray-700">🗓️ {offer.cleaningDetails.frequency}, Area {offer.cleaningDetails.area} , {offer.cleaningDetails.cleaners} cleaners</p>
                                </div>
                            )}

                            {/* Helper Details */}
                            {offer.helperDetails && (
                                <div className="p-3 border rounded-lg bg-gray-100">
                                    <h4 className="text-lg font-semibold flex items-center gap-2"><FaUserFriends className="text-purple-600" /> Helper</h4>
                                    <p className="text-gray-700">🗓️ {offer.helperDetails.frequency}, {offer.helperDetails.hours} hours, {offer.helperDetails.helpers} helpers, {offer.helperDetails.floors} floors, Elevator: {offer.helperDetails.elevator}</p>
                                </div>
                            )}
                        </div>
                        <button
                            onClick={() => handleAddToBooking(offer)}
                            disabled={loadingBookingId === offer._id}
                            className={`mt-4 px-4 py-2 rounded transition text-white ${loadingBookingId === offer._id
                                    ? "bg-gray-400 cursor-not-allowed"
                                    : "bg-yellow-400 hover:bg-blue-700"
                                }`}
                        >
                            {loadingBookingId === offer._id ? "Please wait..." : "Add to Booking"}
                        </button>


                    </div>


                ))}
            </div>
        </div>
    );
};

export default Offers;