import React, { useState, useEffect } from "react";
import axios from "../../Https/Axios";
import { PartnerApiUrl } from "../../Https/AdminSideAxiosUrls"
import { Button, Modal, Form } from "react-bootstrap";
import { FaEdit, FaTrashAlt } from "react-icons/fa";
import Swal from "sweetalert2";

const API_URL = PartnerApiUrl;

const Partners = () => {
    const [partners, setPartners] = useState([]);
    const [showModal, setShowModal] = useState(false);
    const [currentPartner, setCurrentPartner] = useState(null);

    // Fetch partners from API
    useEffect(() => {
        fetchPartners();
    }, []);

    const fetchPartners = async () => {
        try {
            const response = await axios.get(API_URL);
            setPartners(response.data.partners);
        } catch (error) {
            console.error("Error fetching partners:", error);
        }
    };

    // Edit partner
    const handleEdit = (partner) => {
        setCurrentPartner(partner);
        setShowModal(true);
    };

    // Save edited partner
    const handleSave = async () => {
        if (!currentPartner) return;

        const token = localStorage.getItem("tchAdminToken"); // Retrieve token

        try {
            await axios.put(
                `${API_URL}/${currentPartner._id}`,
                currentPartner,
                {
                    headers: {
                        Authorization: `Bearer ${token}`, // Add token to headers
                    },
                }
            );
            fetchPartners(); // Refresh list
            setShowModal(false);
        } catch (error) {
            console.error("Error updating partner:", error);
        }
    };

    // Delete partner

    const handleDelete = async (id) => {
      const token = localStorage.getItem("tchAdminToken"); // Retrieve token
    
      Swal.fire({
        title: "Are you sure?",
        text: "Are you sure you want to delete? If Yes, then it will be deleted permanently!",
        icon: "warning",
        showCancelButton: true,
        confirmButtonColor: "#d33",
        cancelButtonColor: "#3085d6",
        confirmButtonText: "Yes, delete it!",
      }).then(async (result) => {
        if (result.isConfirmed) {
          try {
            await axios.delete(`${API_URL}/${id}`, {
              headers: {
                Authorization: `Bearer ${token}`,
              },
            });
    
             // Refresh list
    
            Swal.fire("Deleted!", "Partner has been deleted.", "success");
            fetchPartners();
          } catch (error) {
            console.error("Error deleting partner:", error);
            Swal.fire("Error!", "Failed to delete partner.", "error");
          }
        }
      });
    };
    

    return (
        <div className="container py-2">
            <div className="grid md:grid-cols-3 lg:grid-cols-4 gap-6">
                {partners.length > 0 ? (
                    partners.map((partner) => (
                        <div
                            key={partner._id}
                            className="p-3 rounded-lg shadow-xl flex flex-col"
                        >
                            <div className="flex justify-start gap-3 items-center">
                                <div className="text-start">
                                    <h2 className="text-xl font-semibold">{partner.name}</h2>
                                </div>
                            </div>
                            <div className="py-3">
                                <p className="mb-2 text-gray-500 text-start">
                                    <strong>Email:</strong> {partner.email}
                                </p>
                                <p className="mb-2 text-gray-500 text-start">
                                    <strong>Phone:</strong> {partner.phone}
                                </p>
                                <p className="mb-2 font-bold text-start">
                                    <strong>License:</strong> {partner.licenseNumber}
                                </p>
                                <p className="mb-2 text-sm text-start text-gray-400">
                                    <strong>Vehicle No:</strong> {partner.vehicleNumber}
                                </p>
                                <p className="mb-2 text-sm text-start">
                                    <strong>Liability Insurance:</strong> {partner.liabilityInsurance ? "Yes" : "No"}
                                </p>
                                <p className="mb-2 text-sm text-start">
                                    <strong>Transport Permit:</strong> {partner.transportPermit ? "Yes" : "No"}
                                </p>
                                <p className="mb-2 text-sm text-start">
                                    <strong>Vans:</strong> {partner.vans}
                                </p>
                            </div>
                            <div className="mt-3 flex justify-center gap-3">
                                <button
                                    className="text-white bg-yellow-400 rounded-pill p-2 px-4 hover:text-white"
                                    onClick={() => handleEdit(partner)}
                                >
                                    <FaEdit size={20} />
                                </button>
                                <button
                                    className="text-white bg-danger rounded-pill p-2 px-4 hover:text-white"
                                    onClick={() => handleDelete(partner._id)}
                                >
                                    <FaTrashAlt size={20} />
                                </button>
                            </div>
                        </div>
                    ))
                ) : (
                    <p className="text-center text-gray-500 col-span-4">No partners found.</p>
                )}
            </div>


            {/* Edit Partner Modal */}
            {currentPartner && (
                <Modal show={showModal} onHide={() => setShowModal(false)} size="lg" centered>
                    <Modal.Header closeButton>
                        <Modal.Title className="fw-bold text-primary">Edit Partner</Modal.Title>
                    </Modal.Header>
                    <Modal.Body>
                        <Form>
                            <div className="row">
                                <div className="col-md-6">
                                    <Form.Group className="mb-3">
                                        <Form.Label className="fw-semibold">Name</Form.Label>
                                        <Form.Control
                                            type="text"
                                            value={currentPartner.name}
                                            onChange={(e) =>
                                                setCurrentPartner({ ...currentPartner, name: e.target.value })
                                            }
                                        />
                                    </Form.Group>
                                </div>
                                <div className="col-md-6">
                                    <Form.Group className="mb-3">
                                        <Form.Label className="fw-semibold">Email</Form.Label>
                                        <Form.Control
                                            type="email"
                                            value={currentPartner.email}
                                            onChange={(e) =>
                                                setCurrentPartner({ ...currentPartner, email: e.target.value })
                                            }
                                        />
                                    </Form.Group>
                                </div>
                            </div>

                            <div className="row">
                                <div className="col-md-6">
                                    <Form.Group className="mb-3">
                                        <Form.Label className="fw-semibold">Phone</Form.Label>
                                        <Form.Control
                                            type="text"
                                            value={currentPartner.phone}
                                            onChange={(e) =>
                                                setCurrentPartner({ ...currentPartner, phone: e.target.value })
                                            }
                                        />
                                    </Form.Group>
                                </div>
                                <div className="col-md-6">
                                    <Form.Group className="mb-3">
                                        <Form.Label className="fw-semibold">License</Form.Label>
                                        <Form.Control
                                            type="text"
                                            value={currentPartner.licenseNumber}
                                            onChange={(e) =>
                                                setCurrentPartner({ ...currentPartner, licenseNumber: e.target.value })
                                            }
                                        />
                                    </Form.Group>
                                </div>
                            </div>

                            <div className="row">
                                <div className="col-md-6">
                                    <Form.Group className="mb-3">
                                        <Form.Label className="fw-semibold">Vehicle Number</Form.Label>
                                        <Form.Control
                                            type="text"
                                            value={currentPartner.vehicleNumber}
                                            onChange={(e) =>
                                                setCurrentPartner({ ...currentPartner, vehicleNumber: e.target.value })
                                            }
                                        />
                                    </Form.Group>
                                </div>
                                <div className="col-md-6">
                                    <Form.Group className="mb-3">
                                        <Form.Label className="fw-semibold">Vans</Form.Label>
                                        <Form.Control
                                            type="number"
                                            value={currentPartner.vans}
                                            onChange={(e) =>
                                                setCurrentPartner({ ...currentPartner, vans: e.target.value })
                                            }
                                        />
                                    </Form.Group>
                                </div>
                            </div>

                            <Form.Group className="mb-3">
                                <Form.Check
                                    type="checkbox"
                                    label="Liability Insurance"
                                    checked={currentPartner.liabilityInsurance}
                                    onChange={(e) =>
                                        setCurrentPartner({ ...currentPartner, liabilityInsurance: e.target.checked })
                                    }
                                />
                                <Form.Check
                                    type="checkbox"
                                    label="Transport Permit"
                                    checked={currentPartner.transportPermit}
                                    onChange={(e) =>
                                        setCurrentPartner({ ...currentPartner, transportPermit: e.target.checked })
                                    }
                                />
                            </Form.Group>

                            <div className="d-flex justify-content-end">
                                <Button variant="success" className="fw-bold px-4 py-2" onClick={handleSave}>
                                    Save Changes
                                </Button>
                            </div>
                        </Form>
                    </Modal.Body>
                </Modal>
            )}
        </div>
    );
};

export default Partners;