import React, { useState } from "react";
import { toast } from "react-toastify";
import { useTranslation } from "react-i18next";
import axios from "../../Https/Axios";
import { WorkWithUsApiUrl } from "../../Https/UserSideAxiosUrls";
import { Form, Button, Row, Col } from "react-bootstrap";

const WorkWithUs = ({ setIsModalOpen }) => {
    const { t } = useTranslation();
    const [loading, setLoading] = useState(false);
    const [formData, setFormData] = useState({
        name: "",
        address: "",
        email: "",
        phone: "",
        isDivingLicense: "",
        licenseNumber: "",
        workBasis: "",
        services: [],
    });

    const [isTerm, setIsTerm] = useState(false);
    const [selectAll, setSelectAll] = useState(false);

    const handleChange = (key, value) => {
        setFormData((prevData) => ({
            ...prevData,
            [key]: value,
        }));
    };

    // Services options from translation file
    const servicesOptions = t("work_with_us.workWithUs.servicesOptions", { returnObjects: true });

    // Mapping service names to English for formData storage
    const serviceMapping = {
        "Transport": "Transporter",
        "Städning": "Cleaner",
        "Rengjøring": "Cleaner",  
        "Flytthjälp": "Moving Assistance",
        "Flyttehjelp": "Moving Assistance" 
    };
    


    const handleServiceChange = (service) => {
        const englishService = serviceMapping[service] || service; // Ensure English mapping

        setFormData(prevData => {
            const updatedServices = prevData.services.includes(englishService)
                ? prevData.services.filter(s => s !== englishService) // Remove if unchecked
                : [...prevData.services, englishService]; // Add if checked

            return { ...prevData, services: updatedServices };
        });

        setSelectAll(formData.services.length === servicesOptions.length);
    };

    const handleSelectAllChange = () => {
        if (selectAll) {
            handleChange("services", []);
        } else {
            handleChange("services", servicesOptions.map(service => serviceMapping[service] || service));
        }
        setSelectAll(!selectAll);
    };

    const handleSubmit = async () => {
        setLoading(true);

        const formDataToSend = new FormData();
        formDataToSend.append("name", formData.name);
        formDataToSend.append("address", formData.address);
        formDataToSend.append("email", formData.email);
        formDataToSend.append("phone", formData.phone);
        formDataToSend.append("isDivingLicense", formData.isDivingLicense);
        formDataToSend.append("licenseNumber", formData.licenseNumber);
        formData.services.forEach((service) => {
            formDataToSend.append("services[]", service);
        });

        try {
            const response = await axios.post(WorkWithUsApiUrl, formDataToSend, {
                headers: {
                    "Content-Type": "application/json",
                },
            });
            alert("Your Request has been sent , we will reach you shortly");

            // toast.success(t("work_with_us.workWithUs.success"));
            setIsModalOpen(true);
            setFormData({
                name: "",
                address: "",
                email: "",
                phone: "",
                licenseNumber: "",
                isDivingLicense: "",
                services: [],
            });
            setSelectAll(false);
        } catch (error) {
            toast.error(error.response?.data?.message || t("work_with_us.workWithUs.error.submitError"));
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="bg-white shadow-lg rounded-3xl p-5 w-full lg:w-[75%] mx-auto">
            <Form>
                <Row>
                    <Col md={6} className="mb-3">
                        <Form.Group>
                            <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.name")}</Form.Label>
                            <Form.Control className="p-2" type="text" value={formData.name} onChange={(e) => handleChange("name", e.target.value)} />
                        </Form.Group>
                    </Col>
                    <Col md={6} className="mb-3">
                        <Form.Group>
                            <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.email")}</Form.Label>
                            <Form.Control className="p-2" type="email" value={formData.email} onChange={(e) => handleChange("email", e.target.value)} />
                        </Form.Group>
                    </Col>
                </Row>
                <Row>
                    <Col md={6} className="mb-3">
                        <Form.Group>
                            <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.address")}</Form.Label>
                            <Form.Control className="p-2" type="text" value={formData.address} onChange={(e) => handleChange("address", e.target.value)} />
                        </Form.Group>
                    </Col>
                    <Col md={6} className="mb-3">
                        <Form.Group>
                            <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.phone")}</Form.Label>
                            <Form.Control className="p-2" type="tel" value={formData.phone} onChange={(e) => handleChange("phone", e.target.value)} />
                        </Form.Group>
                    </Col>
                </Row>
                <Row>
                    <Col md={6} className="mb-3">
                        <Form.Group>
                            <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.license")}</Form.Label>
                            <Form.Select
                                className="p-2"
                                value={formData.isDivingLicense}
                                onChange={(e) => handleChange("isDivingLicense", e.target.value)}>
                                <option value="">{t("work_with_us.workWithUs.workBasisOptions.full_time")}</option>
                                <option value="yes">Ja</option>
                                <option value="no">Nej</option>
                            </Form.Select>
                        </Form.Group>
                    </Col>
                    <Col md={6} className="mb-3">
                        <Form.Group>
                            <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.licenseNumber")}</Form.Label>
                            <Form.Control className="p-2" type="text" value={formData.licenseNumber} onChange={(e) => handleChange("licenseNumber", e.target.value)} />
                        </Form.Group>
                    </Col>
                </Row>
                <Form.Group className="mb-3">
                    <Form.Label className="text-black font-bold">{t("work_with_us.workWithUs.services")}</Form.Label>
                    <Form.Check
                        type="checkbox"
                        label={t("work_with_us.workWithUs.selectAll")}
                        checked={selectAll}
                        onChange={handleSelectAllChange}
                    />
                    {servicesOptions.map(service => (
                        <Form.Check
                            key={service}
                            type="checkbox"
                            label={service}
                            checked={formData.services.includes(serviceMapping[service] || service)}
                            onChange={() => handleServiceChange(service)}
                        />
                    ))}
                </Form.Group>

                <Form.Group className="mb-3">
                    <Form.Check className="p-2" type="checkbox" label={t("work_with_us.workWithUs.terms")} checked={isTerm} onChange={() => setIsTerm(!isTerm)} />
                </Form.Group>

                <div className="flex gap-3 w-full justify-end self-start mt-8">
                    <Button className="px-4 py-3 w-56 text-white border border-[#1CAC78] !bg-[#1CAC78]" onClick={handleSubmit} disabled={loading}>
                        {loading ? t("work_with_us.workWithUs.loading") : t("work_with_us.workWithUs.submit")}
                    </Button>
                </div>
            </Form>
        </div>
    );
};

export default WorkWithUs;