import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import { HiChevronDown, HiChevronUp } from "react-icons/hi";

const FAQTWO = () => {
    const { t } = useTranslation();
    const [expandedIndex, setExpandedIndex] = useState(null);

    const toggleFAQ = (index) => {
        setExpandedIndex(expandedIndex === index ? null : index);
    };

    const faqData = t("faq.questions", { returnObjects: true }) || [];

    return (
        <div className="flex flex-col justify-center items-center  bg-opacity-4 px-24 w-full mt-20">
            <div className="flex gap-10 items-end w-full uppercase">
                <div className="flex flex-col flex-1 shrink w-full basis-0 min-w-[240px] max-md:max-w-full">
                    <div data-aos="fade-right" className="hidden sm:flex flex-wrap gap-6 items-center w-full text-2xl font-bold leading-none text-emerald-500 whitespace-nowrap tracking-[5.52px] max-md:max-w-full">
                        <div className="shrink-0 self-stretch my-auto h-0.5 border-2 border-emerald-500 border-solid w-[86px]" />
                        <div className="self-stretch my-auto">{t("faq.heading")}</div>
                    </div>
                </div>
            </div>
            <div className="flex flex-col mt-10 w-full">
                {faqData.map((faq, index) => (
                    <div
                        key={index}
                        className="flex overflow-hidden flex-col py-8 pr-11 pl-3.5 mt-10 w-full rounded-xl border border-solid bg-slate-100 border-sky-800 border-opacity-70  shadow-[0px_4px_4px_rgba(0,0,0,0.25)] max-md:pr-5 max-md:max-w-full cursor-pointer"
                        onClick={() => toggleFAQ(index)}
                    >
                        <div className="flex w-full justify-between flex-wrap gap-10 items-center text-xl font-semibold leading-relaxed text-zinc-800 max-md:mr-2 max-md:max-w-full">
                            <div className="self-stretch my-auto">{faq.question}</div>
                            {expandedIndex === index ? <HiChevronUp size={24} /> : <HiChevronDown size={24} />}
                        </div>
                        {expandedIndex === index && (
                            <div className="mt-2.5 text-lg leading-8 text-stone-900 text-opacity-80 max-md:max-w-full">
                                {faq.answer || "Answer coming soon! Please check back later."}
                            </div>
                        )}
                    </div>
                ))}
            </div>
        </div>
    );
};

export default FAQTWO;
