import { useState } from "react";
import { Modal, Button, Form } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import bgImage from "../../assets/servicessection/helper.jpg";

const HelperService = ({ onSave }) => {
    const { t } = useTranslation();
    const [show, setShow] = useState(false);
    const [amount, setAmount] = useState(399);
    const [floorRate, setFloorRate] = useState(100);

    const [formData, setFormData] = useState({
        hours: "",
        noofhelpers: "",
        haselavator: "",
        noOfFloors: "" // New field for floors
    });

    const handleClose = () => setShow(false);
    const handleShow = () => setShow(true);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData((prevData) => ({
            ...prevData,
            [name]: value,
            ...(name === "haselavator" && value === "yes" ? { noOfFloors: "" } : {}) // Reset noOfFloors if "yes" is selected
        }));
    };

    const handleSubmit = () => {
        if (formData.hours && formData.noofhelpers) {
            const hourlyRate = amount;
            const floorCostPerFloor = floorRate;
    
            const totalCost = formData.noofhelpers * formData.hours * hourlyRate;
            let floorCost = 0;
            let floorCostText = "";
    
            if (formData.haselavator === "no" && formData.noOfFloors > 0) {
                floorCost = formData.noOfFloors * floorCostPerFloor;
                floorCostText = `${formData.noOfFloors} floors * ${floorCostPerFloor} SEK = ${floorCost}`;
            }
    
            const grandTotal = totalCost + floorCost;
            const updatedData = {
                Hours: formData.hours,
                Helpers: formData.noofhelpers,
                Elevator: formData.haselavator,
                TotalCost: `${formData.hours} hours * ${formData.noofhelpers} helpers * ${hourlyRate} SEK = ${totalCost} SEK`,
                ...(floorCost > 0 && { FloorCost: `${floorCostText} SEK` }), // If floorCost is 0, don't add this field
                Total: `${grandTotal} SEK`
            };
    
            onSave("Helper", updatedData);
    
            setFormData({
                hours: "",
                noofhelpers: "",
                haselavator: "",
                noOfFloors: ""
            });
            handleClose();
        }
    };
    


    return (
        <div className="flex justify-center items-center bg-gray-200">
            {/* Card */}
            <div
                className="relative w-full h-72 bg-cover bg-center rounded-lg shadow-lg overflow-hidden"
                style={{ backgroundImage: `url(${bgImage})` }}
            >
                <div className="absolute inset-0 bg-black bg-opacity-50 flex flex-col items-start text-white p-4">
                    <h2 className="text-2xl mt-10 font-bold">{t("helperService.title")}</h2>
                    <span className="mt-2 uppercase tracking-wide">
                        {t("helperService.perKmCost")} <span className="amount">{amount}</span>
                        <span className="currency"> SEK </span>
                    </span>
                    <p className="mt-2">{t("helperService.description")}</p>
                    <button
                        onClick={handleShow}
                        className="mt-4 px-16 py-2 bg-green-600 text-white rounded-md transition"
                    >
                        {t("helperService.selectButton")}
                    </button>
                </div>
            </div>

            {/* Modal */}
            <Modal show={show} onHide={handleClose} centered size="lg">
                <Modal.Body className="p-5 rounded-md">
                    <h2 className="text-4xl font-bold mb-4">{t("helperService.modalTitle")}</h2>
                    <Form>
                        <Form.Group className="mb-3">
                            <Form.Control
                                type="text"
                                name="hours"
                                placeholder={t("helperService.hoursPlaceholder")}
                                onChange={handleChange}
                                value={formData.hours}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Control
                                type="text"
                                name="noofhelpers"
                                placeholder={t("helperService.helpersPlaceholder")}
                                onChange={handleChange}
                                value={formData.noofhelpers}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>
                        <Form.Group className="mb-4">
                            <Form.Label>{t("helperService.elevatorLabel")}</Form.Label>
                            <Form.Select
                                name="haselavator"
                                value={formData.haselavator}
                                onChange={handleChange}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            >
                                <option value="">{t("helperService.selectOption")}</option>
                                <option value="yes">{t("helperService.yes")}</option>
                                <option value="no">{t("helperService.no")}</option>
                            </Form.Select>
                        </Form.Group>

                        {/* Show "How many floors" field only if "No" is selected */}
                        {formData.haselavator === "no" && (
                            <Form.Group className="mb-3">
                                <Form.Control
                                    type="number"
                                    name="noOfFloors"
                                    placeholder="How many no of floors?"
                                    onChange={handleChange}
                                    value={formData.noOfFloors}
                                    className="border border-gray-300 py-3 rounded-md p-2"
                                />
                            </Form.Group>
                        )}

                        <div className="flex justify-end gap-2">
                            <Button
                                variant="success"
                                className="px-4 py-2 btn-lg text-white rounded-md"
                                onClick={handleClose}
                            >
                                {t("helperService.cancel")}
                            </Button>
                            <Button
                                className="px-4 py-2 text-white border-0 btn-lg rounded-md"
                                onClick={handleSubmit}
                                style={{ backgroundColor: "#035E89" }}
                            >
                                {t("helperService.addService")}
                            </Button>
                        </div>
                    </Form>
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default HelperService;