import React from "react";
import { useTranslation } from "react-i18next";
import { ServiceCard } from "./ServicesCard";
import service_1 from "../../assets/servicessection/service_1.png"
import service_2 from "../../assets/servicessection/service_2.png"
import service_3 from "../../assets/servicessection/service_3.png"
export const ServicesSection = () => {
    const { t } = useTranslation();

    const servicesData = [
        {
            title: t("services.professional_cleaning.title"),
            description: t("services.professional_cleaning.description"),
            isHighlighted: true,
            image: service_1
        },
        {
            title: t("services.safe_transport.title"),
            description: t("services.safe_transport.description"),
            isHighlighted: true,
            image: service_2
        },
        {
            title: t("services.reliable_moving_support.title"),
            description: t("services.reliable_moving_support.description"),
            isHighlighted: true,
            image: service_3
        }
    ];

    return (
        <div className="flex flex-col w-full items-center justify-center mt-10 sm:mt-0">
            <div className="flex flex-col w-11/12">
                <div className="flex flex-col w-full uppercase max-md:max-w-full">
                    <div data-aos="fade-right" className="flex flex-wrap gap-6 items-center w-full text-2xl font-bold leading-none text-[#1CAC78] tracking-[5.52px] max-md:max-w-full">
                        <div className="shrink-0 self-stretch my-auto rounded-md h-0.5 border-2 border-[#1CAC78] border-solid w-[86px]" />
                        <div className="self-stretch my-auto">{t("services.title")}</div>
                    </div>
                    <div data-aos="fade-up-right" className="mt-4 text-4xl font-semibold leading-tight text-sky-800 max-md:max-w-full">
                        <span className="font-bold">{t("services.what")}</span>
                        <span className="font-bold text-sky-800"> {t("services.we_do")}</span>
                    </div>
                </div>
                <div className="gap-10 -start mt-20 place-content-center place-items-center grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3">
                    {servicesData.map((service, index) => (
                        <ServiceCard
                            key={index}
                            title={service.title}
                            image={service.image}
                            description={service.description}
                            isHighlighted={service.isHighlighted}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
};


export default ServicesSection;