import React, { useState } from "react";
import { Modal, Button } from "react-bootstrap";
import "bootstrap/dist/css/bootstrap.min.css";
import { useTranslation } from "react-i18next";
import TransportService from "./Transport";
import HelperService from "./Helper";
import CleanerService from "./Cleaner";
import axios from "../../Https/Axios";
import { useNavigate } from 'react-router-dom';

import { BookingsApiUrl } from "../../Https/UserSideAxiosUrls"
const GetOfferMain = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [showDiscountModal, setShowDiscountModal] = useState(false);
  const [rutApplied, setRutApplied] = useState(false);
  const [personnummer, setPersonnummer] = useState("");
  const [paymentMethod, setPaymentMethod] = useState("");
  const [entries, setEntries] = useState([]);
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    address: "",
    bookingDate: "",
    scheduledTime: "",
    status: "pending",
  });

  const handleSave = (type, serviceData) => {
    setEntries([...entries, { type, ...serviceData }]);
  };

  const handleRemove = (index) => {
    setEntries(entries.filter((_, i) => i !== index));
  };

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // const calculateTotalPrice = () => {
  //   return entries.reduce((total, service) => {
  //     const cost = parseFloat(
  //       (service.totalCost || service.Total || "SEK 0").replace(/[^\d.]/g, "")
  //     );
  //     return total + (isNaN(cost) ? 0 : cost);
  //   }, 0);
  // };

  const calculateTotalPrice = () => {
    const total = entries.reduce((total, service) => {
      const cost = parseFloat(
        (service.totalCost || service.Total || "SEK 0").replace(/[^\d.]/g, "")
      );
      return total + (isNaN(cost) ? 0 : cost);
    }, 0);

    return rutApplied ? total * 0.5 : total;
  };


  // const handleCheckboxChange = () => {
  //   setShowDiscountModal(true);
  // };

  const handleCheckboxChange = () => {
    if (rutApplied) {
      // If already applied, uncheck it and clear the personnummer
      setRutApplied(false);
      setPersonnummer("");
    } else {
      // If not applied, show the modal to enter personnummer
      setShowDiscountModal(true);
    }
  };


  const handleSaveDiscount = () => {
    if (personnummer.trim() === "") {
      alert("Vänligen ange ditt personnummer.");
      return;
    }
    setRutApplied(true);
    setShowDiscountModal(false);
  };

  const handleCloseDiscount = () => {
    setShowDiscountModal(false);
  };



  const formatServiceData = () => {
    return entries.map((service) => {
      if (service.type === "Cleaning") {
        return {
          serviceType: service.type,
          cleaningArea: service.cleaninarea,
          cleaners: service.cleaners,
          squareMeters: service.squaremeters,
          cleanerCost: service.cleanerCost,
          totalCost: service.totalCost,
        };
      } else if (service.type === "Transport") {
        return {
          serviceType: service.type,
          from: service.from,
          to: service.to,
          distance: service.Distance,
          distanceCost: service.DistanceCost,
          total: service.Total,
        };
      } else if (service.type === "Helper") {
        return {
          serviceType: service.type,
          hours: service.Hours,
          helpers: service.Helpers,
          elevator: service.Elevator,
          totalCost: service.TotalCost,
          floorCost: service.FloorCost,
          total: service.Total,
        };
      }
      return service;
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();


    if (entries.length === 0) {
      alert("Please add at least one service before booking.");
      return;
    }

    const totalCost = calculateTotalPrice();
    const payload = {
      ...formData,
      price: `SEK ${totalCost}`,
      serviceData: formatServiceData(),
    };

    try {
      const response = await axios.post(BookingsApiUrl, payload);
      alert("Booking Sent, Please Pay to Proceed More!");
      if (paymentMethod === "visa") {
        navigate("/stripe-payment", { state: { totalCost } });
      } else if (paymentMethod === "klarna") {
        navigate("/klarna-payment", { state: { totalCost } });
      } else {
        alert("Please select a payment method.");
      }

    } catch (error) {
      console.error("Error:", error);
      alert("Failed to submit booking.");
    }
  };

  return (
    <div className="container mt-5 py-40">
      <div className="row">
        <div className="col-md-8">
          {/* {entries.map((entry, index) => (
            <div key={index} className="p-3 mb-3 bg-gray-100 rounded shadow position-relative">
              <button
                className="btn btn-danger position-absolute top-0 end-0 m-2"
                onClick={() => handleRemove(index)}
              >
                ❌
              </button>
              <h5 className="font-bold text-2xl mb-3">{entry.type} Entry</h5>
              {Object.keys(entry).map((key, i) =>
                key !== "type" ? <p key={i}><strong>{key}:</strong> {entry[key]}</p> : null
              )}
            </div>
          ))} */}

          <form className="border p-4 rounded shadow" onSubmit={handleSubmit}>
            <h4 className="mb-3 text-5xl font-bold">{t("getoffer.bookNow")}</h4>
            <p className="text-muted text-xl">{t("getoffer.bookNowDescription")}</p>

            <div className="mb-3">
              <label className="form-label font-bold">{t("getoffer.fullName")}</label>
              <input type="text" name="name" className="form-control py-3" onChange={handleChange} required />
            </div>

            <div className="mb-3">
              <label className="form-label font-bold">{t("getoffer.email")}</label>
              <input type="email" name="email" className="form-control py-3" onChange={handleChange} required />
            </div>

            <div className="mb-3">
              <label className="form-label font-bold">{t("getoffer.phone")}</label>
              <input type="tel" name="phone" className="form-control py-3" onChange={handleChange} required />
            </div>

            <div className="mb-3">
              <label className="form-label font-bold">{t("getoffer.address")}</label>
              <input type="text" name="address" className="form-control py-3" onChange={handleChange} required />
            </div>

            <div className="mb-3">
              <label className="form-label font-bold">{t("getoffer.date")}</label>
              <input type="date" name="bookingDate" className="form-control py-3" onChange={handleChange} required />
            </div>

            <div className="mb-3">
              <label className="form-label font-bold">{t("getoffer.time")}</label>
              <input type="time" name="scheduledTime" className="form-control py-3" onChange={handleChange} required />
            </div>

            {entries.map((entry, index) => (
              <div key={index} className="p-3 mb-3 bg-gray-100 rounded shadow position-relative">
                <button
                  className="btn btn-danger position-absolute top-0 end-0 m-2"
                  onClick={() => handleRemove(index)}
                >
                  ❌
                </button>
                <h5 className="font-bold text-2xl mb-3">{entry.type} Entry</h5>
                {Object.keys(entry).map((key, i) =>
                  key !== "type" ? <p key={i}><strong>{key}:</strong> {entry[key]}</p> : null
                )}
              </div>
            ))}

            {entries.length > 0 && (
              <div className="my-4 p-3 bg-light border flex justify-between rounded text-center">
                <div className="form-check mb-2 flex justify-center gap-2">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    id="rutDiscount"
                    onChange={handleCheckboxChange}
                    checked={rutApplied}
                  />
                  <label className="form-check-label fw-bold" htmlFor="rutDiscount">
                  {t("getoffer.discount")}
                  </label>
                </div>

                <h5 className="mb-0">
                  {/* {t("getoffer.totalCost") || "Total Cost"}:{" "} */}
                  Total Cost: {" "}
                  <span className="text-success fw-bold">SEK {calculateTotalPrice()}</span>
                </h5>
              </div>
            )}


            <div className="mb-3">
              <label className="form-label fw-bold d-block">Select Payment Method:</label>
              <div className="form-check form-check-inline">
                <input
                  className="form-check-input"
                  type="radio"
                  name="paymentMethod"
                  id="visaCard"
                  value="visa"
                  onChange={(e) => setPaymentMethod(e.target.value)}
                  required
                />
                <label className="form-check-label" htmlFor="visaCard">Visa Card</label>
              </div>

              <div className="form-check form-check-inline">
                <input
                  className="form-check-input"
                  type="radio"
                  name="paymentMethod"
                  id="klarna"
                  value="klarna"
                  onChange={(e) => setPaymentMethod(e.target.value)}
                />
                <label className="form-check-label" htmlFor="klarna">Klarna</label>
              </div>
            </div>


            <button type="submit" className="btn btn-lg text-white w-100 mt-3" style={{ backgroundColor: "#035E89" }}>
              {t("getoffer.submit")}
            </button>
          </form>
        </div>

        <div className="col-md-4">
          <div className="flex flex-col gap-4">
            <TransportService onSave={handleSave} />
            <HelperService onSave={handleSave} />
            <CleanerService onSave={handleSave} />
          </div>
        </div>
      </div>


      <Modal show={showDiscountModal} onHide={handleCloseDiscount} centered>
        <Modal.Header closeButton>
          <Modal.Title> {t("getoffer.confirmation")}</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <label className="form-label fw-bold">{t("getoffer.personalnumber")}</label>
          <input
            type="text"
            className="form-control"
            value={personnummer}
            onChange={(e) => setPersonnummer(e.target.value)}
            placeholder="Ex: 19900101-1234"
          />
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleCloseDiscount}>
            Close
          </Button>
          <Button variant="primary" onClick={handleSaveDiscount}>
            Save
          </Button>
        </Modal.Footer>
      </Modal>

    </div>
  );
};

export default GetOfferMain;