import React from "react";
import { FaFacebook, FaInstagram, FaEnvelope, FaPhone } from "react-icons/fa";
import { Link } from "react-router-dom";
import { useTranslation } from "react-i18next";
import logo from "../../assets/logo_new.png"

function Footer() {
    const { t } = useTranslation();
    const footer = t("footer", { returnObjects: true }) || [];
    return (
        <div className="pt-16 mt-10" style={{backgroundColor:"#F6F6F6"}}>
            <div className="grid gap-10 row-gap-6 mb-8 sm:grid-cols-4 lg:grid-cols-6 md:px-24 lg:px-8 px-4">
                <div className="sm:col-span-2">
                    <Link to="/">
                    <img src={logo} className="w-32" alt="Logo" />

                    </Link>
                    <div className="lg:max-w-sm">
                        <div className="flex items-center my-2 space-x-3">
                            <a
                                href="https://m.facebook.com/100076726356313/"
                                className="hover:text-gray-900 text-gray-500"
                                target="_blank"
                                rel="noopener noreferrer"
                            >
                                <FaFacebook size={20} />
                            </a>
                            <a
                                href="https://www.instagram.com/_forareakuten_?igsh=MXJqZHJ4MWhocTNleA=="
                                className="hover:text-gray-900 text-gray-500"
                                target="_blank"
                                rel="noopener noreferrer"
                            >
                                <FaInstagram size={20} />
                            </a>
                        </div>
                        <p className="text-sm text-gray-500">{t("footer.followUs")}</p>
                    </div>
                </div>
                <div>
                    <p className="text-base font-bold tracking-wide text-gray-900">
                        {t("footer.pages.title")}
                    </p>
                    <div className="flex flex-col mt-5 gap-3">
                        <Link
                            to="/"
                            className="hover:scale-x-110 hover:rotate-6 duration-250 transition-all text-decoration-none text-black"
                        >
                            {t("footer.pages.home")}
                        </Link>
                        <Link
                            to="/about-us"
                            className="hover:scale-x-110 hover:rotate-6 duration-250 transition-all text-decoration-none text-black"
                        >
                            {t("footer.pages.about")}
                        </Link>
                        <Link
                            to="/partner"
                            className="hover:scale-x-110 hover:rotate-6 duration-250 transition-all text-decoration-none text-black"
                        >
                            {t("footer.pages.partner")}
                        </Link>
                        <Link
                            to="/work"
                            className="hover:scale-x-110 hover:rotate-6 duration-250 transition-all text-decoration-none text-black"
                        >
                            {t("footer.pages.work")}
                        </Link>
                    </div>
                </div>
                <div className="space-y-2 text-sm">
                    <p className="text-base font-bold tracking-wide text-gray-900">
                        {t("footer.contact.title")}
                    </p>
                    <div className="flex mt-5">
                        <FaPhone className="h-5 w-5 mr-1 text-gray-800" />
                        <a
                            href={`tel:${t("footer.contact.phone")}`}
                            className="transition-colors duration-300 text-[#4B4B4B] hover:text-gray-700 text-decoration-none mb-2"
                        >
                            {t("footer.contact.phone")}
                        </a>
                    </div>
                    <div className="flex">
                        <FaEnvelope className="h-5 w-5 mr-1 text-gray-800" />
                        <a
                            href={`mailto:${t("contact.email")}`}
                            className="transition-colors duration-300 text-[#4B4B4B] hover:text-gray-700 text-decoration-none mb-2"
                        >
                            {t("footer.contact.email")}
                        </a>
                    </div>
                    <div className="flex items-center">
                        <span className="mr-2 text-gray-800">📍</span>
                        <a
                            href="https://www.google.com/maps?q=Blidvädersgatan+22,+418+30+Göteborg,+Sweden"
                            target="_blank"
                            rel="noopener noreferrer"
                            className="transition-colors duration-300 text-[#4B4B4B] hover:text-gray-700 text-decoration-none mb-2"
                        >
                            {t("footer.contact.address")}
                        </a>
                    </div>
                </div>
                <div className="sm:col-span-2 sm:flex flex-col">
                    <p className="text-base font-bold tracking-wide text-gray-900">
                        {t("footer.popularCities")}
                    </p>
                    <div className="grid grid-cols-2 mt-2">
                        {t("footer.cities", { returnObjects: true }).map((city, index) => (
                            <span key={index} className="hover:scale-105 duration-250 transition-all">
                                {city}
                            </span>
                        ))}
                    </div>
                </div>
            </div>
            <div className="flex items-center gap-3 sm:gap-0 justify-center flex-col-reverse bg-[#075985] sm:justify-between py-2 md:px-24 lg:px-8 px-4 border-t lg:flex-row">
                <p className="text-sm text-white">
                    {t("footer.copyright", { year: new Date().getFullYear() })}
                </p>
            </div>
        </div>
    );
}

export default Footer;