import { useState } from "react";
import WorkWithUs from "./WorkWithUs";
import Partners from "./Partners";
import Employees from "./Employees";

const TabSwitcher = () => {
  const [activeTab, setActiveTab] = useState("employees");

  return (
    <div className="container mt-6">
      <h1 className="text-3xl font-bold mb-6"> Peoples and Roles </h1>
      <div className="flex flex-wrap justify-center gap-4 border-2 border-yellow-400 md:rounded-full">
        <button
          className={`px-10 py-2 rounded-full transition-all ${
            activeTab === "employees"
              ? "bg-yellow-400 text-black font-bold shadow-md"
              : "text-gray-700 font-bold"
          }`}
          onClick={() => setActiveTab("employees")}
        >
          Employees
        </button>
        <button
          className={`px-10 py-2 rounded-full transition-all ${
            activeTab === "partners"
              ? "bg-yellow-400 text-black font-bold shadow-md"
              : "text-gray-700 font-bold"
          }`}
          onClick={() => setActiveTab("partners")}
        >
          Partners
        </button>
        <button
          className={`px-10 py-2 rounded-full transition-all ${
            activeTab === "workWithUs"
              ? "bg-yellow-400 text-black font-bold shadow-md"
              : "text-gray-700 font-bold"
          }`}
          onClick={() => setActiveTab("workWithUs")}
        >
          Work With Us
        </button>
      </div>

      {/* Tab Content */}
      <div className="mt-6  ">
        {activeTab === "employees" && <Employees />}
        {activeTab === "partners" && <Partners />}
        {activeTab === "workWithUs" && <WorkWithUs />}
      </div>
    </div>
  );
};

export default TabSwitcher;