import React from "react";
import { useTranslation } from "react-i18next";
import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";
import {Link} from "react-router-dom";
import cleaning from "../../assets/aboutus/cleaning.jpg"
import transport from "../../assets/aboutus/transport.jpg"
import moving from "../../assets/aboutus/moving.jpg"
const ServicesSlider = () => {
  const { t } = useTranslation();

  const services = [
    {
      key: "cleaning",
      image: cleaning,
      link: "/book-now"
    },
    {
      key: "transport",
      image: transport,
      link: "/book-now"
    },
    {
      key: "movingHelp",
      image: moving,
      link: "/book-now"
    }
  ];

  return (
    <section className="relative overflow-hidden bg-white md:pb-32 lg:pb-32 space-y-20 md:mt-0 lg:mt-0 mt-6">


      <h1 className="text-4xl md:text-6xl lg:text-7xl w-full text-center font-bold mb-20">
        {t("slider.services.title")}
      </h1>

      <div className="relative w-full max-w-7xl mx-auto px-4 lg:px-8">
        <Swiper
          modules={[Autoplay]}
          slidesPerView={1}
          spaceBetween={32}
          loop={true}
          autoplay={{
            delay: 2500,
            disableOnInteraction: false,
          }}
        >
          {services.map((service, index) => (
            <SwiperSlide key={index}>
              <div className="flex flex-col lg:flex-row items-center lg:items-start gap-8">
                <div className="w-full lg:w-1/2">
                  <img
                    src={service.image}
                    alt={t(`slider.services.${service.key}.title`)}
                    className="w-full rounded-xl shadow-2xl"
                  />
                </div>
                <div className="w-full lg:w-1/2 flex flex-col justify-center">
                  <h2 className="text-3xl lg:text-4xl font-bold tracking-tight text-black text-start">
                    {t(`slider.services.${service.key}.title`)}
                  </h2>
                  <p className="mt-8 text-lg text-gray-700 text-start">
                    {t(`slider.services.${service.key}.description`)}
                  </p>
                </div>
              </div>
            </SwiperSlide>
          ))}
          <div className="flex items-center justify-center">
            <div className="mt-10 flex items-center justify-start ">
              <Link href={"/book-now"}>
                <button className="gap-2.5 self-stretch hover:scale-105 transition-all duration-250 px-9 py-3.5 my-auto sm:w-48 hover:bg-emerald-600 text-white rounded border border-[#1CAC78] bg-[#1CAC78] border-solid min-h-[46px] max-md:px-5">
                  {t("slider.services.bookNow")}
                </button>
              </Link>
            </div>
          </div>
        </Swiper>
      </div>
    </section>
  );
};

export default ServicesSlider;