import React, { useState } from "react";
import axios from "../../Https/Axios";
import { AdminLoginApiUrl } from "../../Https/AdminSideAxiosUrls";
import { useNavigate } from "react-router-dom";
import { FaEye, FaEyeSlash, FaUser, FaLock } from "react-icons/fa";
import { motion } from "framer-motion";
import loginBg from "../../assets/login.jpg";

const LoginForm = () => {
  const [error, setError] = useState("");
  const [passwordVisible, setPasswordVisible] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const navigate = useNavigate();

  const handleLogin = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    const email = e.target.email.value.trim();
    const password = e.target.password.value.trim();

    try {
      const response = await axios.post(AdminLoginApiUrl, { email, password });

      if (response.data.token) {
        localStorage.setItem("tchAdminToken", response.data.token);
        navigate("/admin/dashboard");
      } else {
        setError(response.data.message || "Invalid credentials, please try again.");
      }
    } catch (err) {
      console.error("Login error:", err);
      setError("Login failed. Please check your credentials and try again.");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-gray-900 px-4">
      <motion.div
        initial={{ opacity: 0, y: 40 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.8, ease: "easeOut" }}
        className="flex flex-wrap max-w-5xl w-full bg-white/10 backdrop-blur-md shadow-2xl rounded-3xl overflow-hidden"
      >
        <div
          className="hidden md:block md:w-1/2 bg-cover bg-center"
          style={{ backgroundImage: `url(${loginBg})`, minHeight: "500px" }}
        ></div>

        <div className="w-full md:w-1/2 p-10 sm:p-12 flex flex-col justify-center bg-gray-900/70 backdrop-blur-lg">
          <h2 className="text-4xl font-extrabold text-center text-white mb-6">
            Admin Login
          </h2>

          {error && (
            <p className="text-red-400 text-center mb-4 font-semibold">{error}</p>
          )}

          <form onSubmit={handleLogin} className="space-y-6">
            <div className="relative">
              <FaUser className="absolute left-4 top-1/2 transform -translate-y-1/2 text-white" />
              <input
                type="email"
                name="email"
                placeholder="Email Address"
                required
                className="w-full pl-12 pr-4 py-3 rounded-xl bg-white/10 text-white placeholder-gray-300 border border-white/30 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all duration-200"
              />
            </div>

            <div className="relative">
              <FaLock className="absolute left-4 top-1/2 transform -translate-y-1/2 text-white" />
              <input
                type={passwordVisible ? "text" : "password"}
                name="password"
                placeholder="Password"
                required
                className="w-full pl-12 pr-12 py-3 rounded-xl bg-white/10 text-white placeholder-gray-300 border border-white/30 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all duration-200"
              />
              <button
                type="button"
                className="absolute right-4 top-1/2 transform -translate-y-1/2 text-white focus:outline-none"
                onClick={() => setPasswordVisible(!passwordVisible)}
              >
                {passwordVisible ? <FaEyeSlash size={18} /> : <FaEye size={18} />}
              </button>
            </div>

            <button
              type="submit"
              className={`w-full py-3 mt-4 rounded-xl text-white font-semibold text-lg transition-all duration-300 shadow-lg ${
                isLoading
                  ? "bg-blue-400 cursor-not-allowed"
                  : "bg-gradient-to-r from-blue-500 to-purple-600 hover:from-blue-600 hover:to-purple-700"
              }`}
              disabled={isLoading}
            >
              {isLoading ? (
                <div className="flex items-center justify-center space-x-2">
                  <svg
                    className="animate-spin h-5 w-5 text-white"
                    xmlns="http://www.w3.org/2000/svg"
                    fill="none"
                    viewBox="0 0 24 24"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    ></circle>
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8v4a4 4 0 00-4 4H4z"
                    ></path>
                  </svg>
                  <span>Signing In...</span>
                </div>
              ) : (
                "Sign In"
              )}
            </button>
          </form>
        </div>
      </motion.div>
    </div>
  );
};

export default LoginForm;