import { useState } from "react";
import axios from "../../Https/Axios";
import {EmployeeApiUrl} from "../../Https/AdminSideAxiosUrls"
const AddEmployeeForm = () => {
  const [employee, setEmployee] = useState({
    name: "",
    email: "",
    address: "",
    phone: "",
    haveDrivingLicense: "",
    licenceNumber: "",
    typeofwork: [],
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setEmployee({ ...employee, [name]: value });
  };

  const handleWorkTypeChange = (e) => {
    const { options } = e.target;
    const selectedOptions = Array.from(options)
      .filter((opt) => opt.selected)
      .map((opt) => opt.value);
    setEmployee({ ...employee, typeofwork: selectedOptions });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    const token = localStorage.getItem("tchAdminToken");
    if (!token) {
      alert("Token not found! Please log in.");
      return;
    }

    const headers = {
      "Content-Type": "application/json",
      Authorization: `Bearer ${token}`,
    };

    try {
      const response = await axios.post(EmployeeApiUrl, employee, { headers });

      if (response.status === 201) {
        alert("Employee added successfully!");
        setEmployee({
          name: "",
          email: "",
          address: "",
          phone: "",
          haveDrivingLicense: "",
          licenceNumber: "",
          typeofwork: [],
        });
      }
    } catch (error) {
      console.error("Error adding employee:", error);
      alert("Failed to add employee.");
    }
  };

  return (
    <div className="mx-auto bg-white p-8 shadow-xl rounded-lg mt-8 border border-gray-200">
      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {[
            { label: "Name", type: "text", name: "name" },
            { label: "Email", type: "email", name: "email" },
            { label: "Address", type: "text", name: "address" },
            { label: "Phone Number", type: "tel", name: "phone" },
          ].map(({ label, type, name }, index) => (
            <div key={index}>
              <label className="block text-gray-600 font-medium mb-1">{label}</label>
              <input
                type={type}
                name={name}
                value={employee[name]}
                onChange={handleChange}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring focus:ring-blue-300 bg-gray-50"
                required
              />
            </div>
          ))}

          {/* Driving License Select Box */}
          <div>
            <label className="block text-gray-600 font-medium mb-1">Have Driving License?</label>
            <select
              name="haveDrivingLicense"
              value={employee.haveDrivingLicense}
              onChange={handleChange}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring focus:ring-blue-300 bg-gray-50"
              required
            >
              <option value="">Select</option>
              <option value="Yes">Yes</option>
              <option value="No">No</option>
            </select>
          </div>

          {/* License Number (Shown only if "Yes" is selected) */}
          {employee.haveDrivingLicense === "Yes" && (
            <div>
              <label className="block text-gray-600 font-medium mb-1">License Number</label>
              <input
                type="text"
                name="licenceNumber"
                value={employee.licenceNumber}
                onChange={handleChange}
                className="w-full p-3 border border-gray-300 rounded-lg focus:ring focus:ring-blue-300 bg-gray-50"
                required
              />
            </div>
          )}

          {/* Multi-Select for Type of Work */}
          <div>
            <label className="block text-gray-600 font-medium mb-1">Type of Work</label>
            <select
              multiple
              name="typeofwork"
              onChange={handleWorkTypeChange}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring focus:ring-blue-300 bg-gray-50"
              required
            >
              {[ "Transporter", "Cleaner", "Moving Assistance"].map((work, i) => (
                <option key={i} value={work}>
                  {work}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="text-end mt-4">
          <button
            type="submit"
            className="bg-yellow-400 text-black px-12 py-3 rounded-lg hover:bg-yellow-500 transition text-lg font-medium"
          >
            Add Employee
          </button>
        </div>
      </form>
    </div>
  );
};

export default AddEmployeeForm;