import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import { Modal, Button, Form } from "react-bootstrap";
import bgImage from "../../assets/servicessection/transport.jpg";

const TransportService = ({ onSave }) => {
    const { t } = useTranslation();
    const [show, setShow] = useState(false);
    const [amount, setAmount] = useState(18);
    const [formData, setFormData] = useState({
        from: "",
        to: "",
        km: "",
        result: ""
    });

    const handleClose = () => setShow(false);
    const handleShow = () => setShow(true);

    const handleChange = (e) => {
        const { name, value } = e.target;
        let updatedFormData = { ...formData, [name]: value };

        if (name === "km") {
            updatedFormData.result = value * amount;
        }

        setFormData(updatedFormData);
    };

    const handleSubmit = () => {
        if (formData.from && formData.to && formData.km) {
            const kmValue = parseFloat(formData.km);
            const totalCost = kmValue * amount;

            const updatedData = {
                from: formData.from,
                to: formData.to,
                Distance: `${kmValue} km`,
                DistanceCost: `${kmValue} km * SEK${amount}/km = SEK${totalCost}`,
                Total: `SEK${totalCost}`
            };
            onSave("Transport", updatedData);
            setFormData({ from: "", to: "", km: "", result: "" });
            handleClose();
        }
    };


    return (
        <div className="flex justify-center items-center bg-gray-200">
            {/* Card */}
            <div className="relative w-full h-72 bg-cover bg-center rounded-lg shadow-lg overflow-hidden"
                style={{ backgroundImage: `url(${bgImage})` }}>
                {/* Transparent Layer */}
                <div className="absolute inset-0 bg-black bg-opacity-50 flex flex-col items-start text-white p-4">
                    <h2 className="text-2xl mt-10 font-bold">{t("transport.title")}</h2>
                    <span className="mt-2 uppercase tracking-wide">
                        {t("transport.perKmCost")} <span className="amount">{amount}</span> <span className="currency">SEK</span>
                    </span>
                    <p className="mt-2">{t("transport.description")}</p>
                    <button onClick={handleShow} className="mt-4 mb-4 px-16 py-2 bg-green-600 text-white rounded-md transition">
                        {t("transport.selectButton")}
                    </button>
                </div>
            </div>

            <Modal show={show} onHide={handleClose} centered size="lg">
                <Modal.Body className="p-5 rounded-md">
                    <h2 className="text-4xl font-bold mb-4">
                        {t("transport.modalTitle")}
                    </h2>
                    <Form>
                        <Form.Group className="mb-3">
                            <Form.Control
                                type="text"
                                name="from"
                                value={formData.from}
                                onChange={handleChange}
                                placeholder={t("transport.fromPlaceholder")}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Control
                                type="text"
                                name="to"
                                value={formData.to}
                                onChange={handleChange}
                                placeholder={t("transport.toPlaceholder")}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>
                        <Form.Group className="mb-4">
                            <Form.Control
                                type="number"
                                name="km"
                                value={formData.km}
                                onChange={handleChange}
                                placeholder={t("transport.kmPlaceholder")}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>

                        {/* Distance Calculation Summary */}
                        {formData.km && (
                            <p className="text-lg font-semibold text-gray-700">
                                Distance: {formData.km} km * {amount} SEK/km = <span className="text-green-600">{formData.result} SEK</span>
                            </p>
                        )}

                        <div className="flex justify-end gap-2 mt-3">
                            <Button variant="success" className="px-4 py-2 btn-lg text-white rounded-md" onClick={handleClose}>
                                {t("transport.cancelButton")}
                            </Button>
                            <Button className="px-4 py-2 text-white border-0 btn-lg rounded-md"
                                onClick={handleSubmit}
                                style={{ backgroundColor: "#035E89" }}>
                                {t("transport.addButton")}
                            </Button>
                        </div>
                    </Form>
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default TransportService;
