import React, { useEffect, useState } from 'react';
import DashBoardNavbar from '../DashboardNavbar/DashboardNavbar';
import AddPeople from '../AddPeople/AddPeople.js';
import Bookings from '../Bookings/Bookings.js';
import DashboardHome from '../DashboardHome/DashboardHome.js';
// import Categories from '../Categories.js'
import Tasks from '../Tasks/Tasks.js';
import TabSwitcher from '../People/People.js';
import AdminNavbar from '../AdminNavbar/AdminNavbar.js';
import Offers from '../Offers/Offers.js';
import BookNowMain from '../AddBooking/BookNowMain.js';
export default function Dashboard() {


    const [selectedComponent, setSelectedComponent] = useState('dashboard'); 
    const handleMenuItemClick = (item) => {
        setSelectedComponent(item);
    };

    return (
        <div className="container-fluid m-0  vh-100">
            <div className="row h-100">
                <div className="col-lg-2 col-md-2 p-0 ">
                    <DashBoardNavbar onItemClick={handleMenuItemClick} />
                </div>
                <div className="col-lg-10 col-md-10 p-0 m-0">
                    <div className="d-none d-lg-block">
                        <AdminNavbar />
                    </div>

                    <div className=" lg:mt-0 mt-24 mx-3 mb-3">

                        {selectedComponent === 'dashboard' && <DashboardHome onItemClick={handleMenuItemClick} />}
                        {selectedComponent === 'addpeople' && <AddPeople />}
                        {selectedComponent === 'bookings' && <Bookings />}
                        {selectedComponent === 'products' && <TabSwitcher />}
                        {selectedComponent === 'tasks' && <Tasks />}
                        {selectedComponent === 'Offers' && <Offers />}
                        {selectedComponent === 'addbookings' && <BookNowMain />}
                        
                        
                    </div>
                </div>
            </div>
        </div>
    );
}