import { useState } from "react";
import { Modal, Button, Form } from "react-bootstrap";
import { useTranslation } from "react-i18next";
import bgImage from "../../assets/servicessection/cleaning.jpg"
const CleanerService = ({ onSave }) => {
    const { t } = useTranslation();
    const [show, setShow] = useState(false);
    const [amount, setAmount] = useState(70);
    const [formData, setFormData] = useState({ area: "", noofcleaners: "" });

    const handleClose = () => setShow(false);
    const handleShow = () => setShow(true);

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

   
    const handleSubmit = () => {
        if (formData.area && formData.noofcleaners) {
            
            const areaCost = parseFloat(formData.area) * 1; // SEK 1 per square foot
            const cleanerCost = parseInt(formData.noofcleaners) * amount; // SEK 70 per cleaner
            const totalCost = areaCost + cleanerCost;

            const serviceData = {
                cleaninarea: `${formData.area} sq ft`,
                cleaners: formData.noofcleaners,
                squaremeters: `${formData.area} sq ft * SEK 1/sq. ft. = ${areaCost}`,
                cleanerCost: `${formData.noofcleaners} cleaners * SEK ${amount} = ${cleanerCost} SEK`,
                totalCost: `${totalCost} SEK`
            };

            onSave("Cleaning", serviceData);
            setFormData({ area: "", noofcleaners: "" });
            handleClose();
        }
    };

    return (
        <div className="flex justify-center items-center bg-gray-200">
            {/* Card */}
            <div className="relative w-full h-72 bg-cover bg-center rounded-lg shadow-lg overflow-hidden"
                style={{ backgroundImage: `url(${bgImage})` }}
            >
                {/* Transparent Layer */}
                <div className="absolute inset-0 bg-black bg-opacity-50 flex flex-col items-start text-white p-4">
                    <h2 className="text-2xl mt-10 font-bold">{t("cleaning.cleaning")}</h2>
                    <span className=" mt-2 uppercase tracking-wide">{t("cleaning.per_km_cost")}

                    <span className="amount">{amount}</span><span className="currency">  SEK </span>

                    </span>
                    <p className="mt-2 ">{t("cleaning.description")}</p>
                    <button onClick={handleShow} className="mt-4 px-16 py-2 bg-green-600 text-white rounded-md transition">
                        {t("cleaning.select")}
                    </button>
                </div>
            </div>

            {/* Modal */}
            <Modal show={show} onHide={handleClose} centered size="lg">
                <Modal.Body className="p-5 rounded-md">
                    <h2 className="text-4xl font-bold mb-4">
                        {t("cleaning.add_cleaning_details")}
                    </h2>
                    <Form>
                        <Form.Group className="mb-3">
                            <Form.Control
                                type="text"
                                onChange={handleChange}
                                name="area"
                                value={formData.area}
                                placeholder={t("cleaning.area_placeholder")}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>
                        <Form.Group className="mb-4">
                            <Form.Control
                                type="text"
                                onChange={handleChange}
                                name="noofcleaners"
                                value={formData.noofcleaners}
                                placeholder={t("cleaning.cleaners_placeholder")}
                                className="border border-gray-300 py-3 rounded-md p-2"
                            />
                        </Form.Group>
                        <div className="flex justify-end gap-2">
                            <Button
                                variant="success"
                                className="px-4 py-2 btn-lg text-white rounded-md"
                                onClick={handleClose}
                            >
                                {t("cleaning.cancel")}
                            </Button>
                            <Button
                                className="px-4 py-2 text-white border-0 btn-lg rounded-md"
                                onClick={handleSubmit}
                                style={{ backgroundColor: "#035E89" }}
                            >
                                {t("cleaning.add_service")}
                            </Button>
                        </div>
                    </Form>
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default CleanerService;