import React, { useState } from "react";
import { useTranslation } from "react-i18next";
import WorkWithUs from "./WorkWithUs";
// import CustomModal from "../components/SuccessModal";
import bg_image from "../../assets/work/cargo.png"

function Work() {
    const [isModalOpen, setIsModalOpen] = useState(false);
    const { t } = useTranslation();



    return (
        <div>
            <div className="relative z-0 pt-40 flex-col flex items-center justify-center w-full max-md:px-5 max-md:pt-24 max-md:pb-28 max-md:max-w-full">
                <img
                    src={bg_image}
                    alt="banner"
                    className="object-cover -z-10 absolute inset-0 size-full"
                />
                <div className="object-cover z-10 absolute inset-0 size-full bg-[#0d0c0c9c]"></div>

                <div className="flex flex-col items-center justify-center z-30 py-10">
                    <h1 className="md:text-6xl lg:text-6xl text-5xl font-bold text-sky-800">
                        <span className="text-white">{t("work.workWithUs.title")}</span>
                    </h1>
                </div>



                <div className="flex rounded-2xl mx-auto my-4 mt-20 mb-20 z-20 w-full items-center justify-center">
                    <WorkWithUs setIsModalOpen={setIsModalOpen} />
                </div>
            </div>

            {/* <CustomModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        heading={t("work.workWithUs.successMessage")}
        description={t("work.workWithUs.successMessage")}
      /> */}
        </div>
    );
}

export default Work;
