import { Link } from "react-router-dom";
import React from "react";
import { useTranslation } from "react-i18next";

export const ServiceCard = ({ title, description, image }) => {
  const { t } = useTranslation();

  return (
    <div className="flex flex-col w-full sm:w-[350px] h-full">
      <div className="flex gap-2.5 justify-center items-center w-full rounded-2xl h-full">
        <div className="flex flex-col flex-1 shrink justify-center items-center self-stretch my-auto w-full rounded-2xl min-h-full min-w-[240px]  border border-slate-300 shadow-lg transition-all duration-300 hover:bg-sky-800 hover:text-white">
          <div className="bg-sky-800 p-3 rounded-full flex items-center justify-center -mt-10 transition-all duration-300 hover:bg-black">
            <img src={image} alt={t(title)} className="w-12 h-12" />
          </div>
          <div className="flex flex-col justify-between items-center pt-5 max-w-full min-h-[207px] w-[300px]">
            <div className="text-xl lg:text-2xl capitalize font-bold text-center  transition-all duration-300 hover:text-white">
              {t(title)}
            </div>
            <div className="mt-3.5 leading-normal text-base0 text-justify transition-all duration-300 hover:text-white">
              {t(description)}
            </div>
          </div>
          <Link to="/book-service">
            <button className="gap-2.5 hover:scale-105 duration-300 self-stretch mx-auto mb-5 px-9 py-3.5 mt-7 max-w-full text-base font-medium text-center uppercase rounded min-h-[46px] w-[254px] bg-emerald-500 text-white transition-all duration-300 hover:bg-emerald-500">
              {t("servicescard.get_offer")}
            </button>
          </Link>
        </div>
      </div>
    </div>
  );
};