import { FiLogOut } from "react-icons/fi";
import { useNavigate } from "react-router-dom";
import { FaUser } from "react-icons/fa";

const AdminNavbar = () => {
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("tchAdminToken");
    navigate("/admin/login");
  };
  return (
    <div className="flex justify-between items-center  text-white py-2 mx-4 border-b-2  border-gray-300">
      {/* Left Side: Image, Name, Email */}

      <div className="flex items-center gap-4">
        <FaUser className="w-16 h-16 text-yellow-400 border-2 border-yellow-400 rounded-full p-3 bg-gray-200" />
        <div>
          <h2 className="text-lg text-black font-semibold">Welcome Admin</h2>
          <p className="text-sm text-gray-300">Manage with Control</p>
        </div>
      </div>


      {/* Right Side: Logout Icon */}
      <button onClick={handleLogout} className="text-red-500 text-xl hover:text-red-500 transition">
        <FiLogOut />
      </button>
    </div>
  );
};

export default AdminNavbar;