import React, { useState } from "react";
import { Form, Button, Row, Col, InputGroup } from "react-bootstrap";
import { useToast } from "../../ToastManager";
// import AddEmployeeForm from "./AddEmployee";
// import AddPartner from "./AddPartner";
import PendingTasks from "./PendingTasks";
import InProgress from "./InProgress";
import Completed from "./Completed";
export default function Tasks() {
  const [activeTab, setActiveTab] = useState("pending");
  return (
    <div className="container mt-6">
      <h1 className="text-3xl font-bold mb-6"> Manage Tasks </h1>
      <div className="flex flex-wrap justify-center gap-4 border-2 border-yellow-400 md:rounded-full">
        <button
          className={`px-10 py-2 rounded-full transition-all ${activeTab === "pending"
              ? "bg-yellow-400 text-black font-bold shadow-md"
              : "text-gray-700  font-bold"
            }`}
          onClick={() => setActiveTab("pending")}
        >
          Pending
        </button>
        <button
          className={`px-10 py-2 rounded-full transition-all ${activeTab === "inprogress"
              ? "bg-yellow-400 text-black font-bold shadow-md"
              : "text-gray-700  font-bold"
            }`}
          onClick={() => setActiveTab("inprogress")}
        >
          In Progress
        </button>
        <button
          className={`px-10 py-2 rounded-full transition-all ${activeTab === "completed"
              ? "bg-yellow-400 text-black font-bold shadow-md"
              : "text-gray-700  font-bold"
            }`}
          onClick={() => setActiveTab("completed")}
        >
          Completed
        </button>
      </div>

      {/* Tab Content */}
      <div className="mt-6">
        {activeTab === "pending" && <><PendingTasks/></>}
        {activeTab === "inprogress" && <><InProgress/></>}
        {activeTab === "completed" && <><Completed/></>}
      </div>
    </div>
  );
}
